/*
 * 物理(4単位)のテキスト本文。このアプリのオリジナル。
 * 書式は js/data/lessons_1.js 冒頭のコメントと同じ。単元の定義は js/data/units_new_phys.js。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 力学の発展 =====
  L.p4_mech = {
    goal: '運動量と力積・反発係数を使って衝突を計算し、等速円運動・単振動・万有引力による運動の式を、自分で導きながら使えるようになる。',
    intro: 'ボウリングの球がピンをはじき飛ばすとき、ぶつかる一瞬の力はとても複雑で、ふつうは測れません。でも「ぶつかる前と後で変わらない量」に目をつけると、力を知らなくても後の速さが分かります。それが【運動量】です。この単元では、衝突の考え方に加えて、ぐるぐる回る運動(円運動)、行ったり来たりする運動(単振動)、そして惑星の運動までを、運動方程式 ma＝F という1本の式から導いていきます。',
    pre: '【運動方程式】質量 m〔kg〕の物体に力 F〔N〕がはたらくと、加速度 a〔m/s²〕は ma＝F を満たします。物理の力学は、ほとんどがこの式から出発します。\n【速度はベクトル】速度は大きさ(速さ)と向きをもつ量です。速さが同じでも、向きが変われば速度は変わったことになります。向きを考えるときは、正の向きを最初に決めて、逆向きはマイナスで表します。\n【力学的エネルギー保存】重力やばねの力だけが仕事をするとき、(1/2)mv²＋mgh(または (1/2)kx²)は一定です。衝突や円運動でもこの考え方を組み合わせて使います。\n【作用・反作用の法則】物体Aが物体Bに力を加えると、BもAに同じ大きさで逆向きの力を同時に加えます。衝突で運動量が保存される理由は、この法則にあります。\n【弧度法(ラジアン)】角度を「半径に対する弧の長さの比」で表す方法です。1周は 2π rad、半周は π rad。半径 r、中心角 θ〔rad〕の弧の長さは rθ です。円運動ではこの表し方を使います。',
    secs: [
      { h: '運動量と力積', t: '物体の「勢い」を表す量として、質量と速度の積 【p＝mv】 を【運動量】といいます。単位は kg·m/s です。重いものほど、速いものほど止めにくい、という感覚を数にしたものです。\nなぜこの量が大切なのかは、運動方程式から分かります。力 F が短い時間 Δt だけはたらいて、速度が v から v′ に変わったとすると、加速度は a＝(v′−v)/Δt です。これを ma＝F に入れて両辺に Δt をかけると、【mv′−mv＝FΔt】 になります。\n右辺の FΔt を【力積】といいます(単位 N·s。kg·m/s と同じ)。つまり【運動量の変化は、受けた力積に等しい】。力が時間とともに変わるときは、F-t グラフの面積が力積になります。\nこの関係を使うと、「同じ運動量の変化でも、時間を長くすれば力は小さくなる」ことが分かります。エアバッグやグローブで衝撃をやわらげるのは、ぶつかる時間を長くしているからです。\n向きに注意します。ボールがはね返るときは、速度の符号が逆になるので、運動量の変化は「速さの差」ではなく「速さの和」で大きくなります。',
        key: '運動量の変化＝力積(mv′−mv＝FΔt)。向きは符号で表し、はね返りでは変化が大きくなる。',
        ex: [{ q: '質量 0.15 kg のボールが 30 m/s で飛んできた。バットで打ち返したら、逆向きに 40 m/s で飛んでいった。バットがボールに与えた力積の大きさは? また、接触時間が 0.010 s のとき、平均の力の大きさは?', hint: '打ち返した向きを正にすると、はじめの速度はマイナスです。', steps: ['打ち返した向きを正とする。はじめの速度 −30 m/s、あとの速度 ＋40 m/s。', '運動量の変化:0.15×40−0.15×(−30)＝6.0＋4.5＝10.5 kg·m/s。', '力積＝運動量の変化なので、力積の大きさは 10.5 N·s(約 11 N·s)。', '平均の力:F＝10.5÷0.010＝1050 N(約 1.1×10³ N)。'], a: '力積 約 11 N·s(10.5 N·s)、平均の力 約 1.1×10³ N', check: '単位を確かめる:N·s÷s＝N。符号をつけずに 40−30 と計算すると 1.5 N·s になり、はね返りを考えていないまちがいだと分かる。' }] },
      { h: '運動量保存の法則', t: '2つの物体が衝突するとき、AがBから受ける力と、BがAから受ける力は、作用・反作用の関係にあり、【同じ大きさで逆向き】、しかも【同じ時間】だけはたらきます。\nだから、Aが受ける力積とBが受ける力積も、同じ大きさで逆向きです。Aの運動量が増えた分だけ、Bの運動量が減ります。その結果、2つの運動量の和は変わりません。\n式:【m₁v₁＋m₂v₂＝m₁v₁′＋m₂v₂′】。これを【運動量保存の法則】といいます。成り立つ条件は「外から力積を受けない(外力がない、または無視できる)」ことです。\n衝突の力がどんなに複雑でも、この式は使えます。力を知らなくてよいのが強みです。分裂(1つの物体が2つに分かれる)や、人がボートの上で動く場合にも使えます。\n注意:運動量は保存されても、運動エネルギーは保存されるとは限りません。くっつく衝突では、運動エネルギーの一部が熱や音、変形に変わります。',
        key: '外力がなければ、運動量の和は保存される(力の中身を知らなくても使える)。運動エネルギーは保存されるとは限らない。',
        ex: [{ q: 'なめらかな水平面上で、質量 2.0 kg の物体Aが 3.0 m/s で進み、静止している質量 1.0 kg の物体Bに衝突して一体になった。衝突後の速さと、衝突で失われた運動エネルギーを求めよ。', hint: '一体になった後は、質量 3.0 kg の1つの物体と考えます。', steps: ['Aの進む向きを正とする。衝突前の運動量の和:2.0×3.0＋1.0×0＝6.0 kg·m/s。', '衝突後の速度を V とすると (2.0＋1.0)V＝6.0 → V＝2.0 m/s。', '衝突前の運動エネルギー:(1/2)×2.0×3.0²＝9.0 J。', '衝突後の運動エネルギー:(1/2)×3.0×2.0²＝6.0 J。', '失われたのは 9.0−6.0＝3.0 J。'], a: '速さ 2.0 m/s、失われた運動エネルギー 3.0 J', check: '一体になる衝突(完全非弾性衝突)では、運動エネルギーは必ず減る。減った値が正になっているので筋が通る。' }] },
      { h: 'はね返り係数(反発係数)', t: '衝突でどれだけはね返るかは、物体の材質で決まります。これを数で表したのが【はね返り係数(反発係数)e】です。\n2物体が一直線上で衝突するとき、【e＝−(v₁′−v₂′)/(v₁−v₂)】。分母は「近づく速さ」、分子は「離れる速さ」を表していて、e は「離れる速さ÷近づく速さ」です。マイナスがつくのは、衝突の前後で相対速度の向きが逆になるからです。\ne の値は 0≦e≦1。【e＝1:弾性衝突】(運動エネルギーも保存される)、【0＜e＜1:非弾性衝突】、【e＝0:完全非弾性衝突】(くっつく)と分類します。\n床や壁のように動かないものとの衝突では、e＝(はね返る速さ)/(当たる速さ) と簡単になります。\n衝突の問題は、ふつう未知数が2つ(v₁′ と v₂′)なので、【運動量保存】と【はね返り係数の式】の2本を連立して解きます。',
        key: '衝突は「運動量保存」と「はね返り係数」の2式を連立する。e＝離れる速さ÷近づく速さ。',
        ex: [{ q: '高さ 2.5 m の所から静かにボールを落とした。床とのはね返り係数が 0.60 のとき、1回目にはね上がる高さは?(g＝9.8 m/s²、空気抵抗は無視)', hint: '落ちる速さ → はね返る速さ → はね上がる高さ、の順に考えます。', steps: ['床に当たる直前の速さ:(1/2)mv²＝mgh より v＝√(2gh)＝√(2×9.8×2.5)＝√49＝7.0 m/s。', 'はね返った直後の速さ:v′＝ev＝0.60×7.0＝4.2 m/s。', 'はね上がる高さ:h′＝v′²/(2g)＝4.2²/19.6＝17.64/19.6＝0.90 m。', '一般に h′＝(ev)²/(2g)＝e²h となる。0.60²×2.5＝0.90 m で一致。'], a: '0.90 m', check: '高さは e 倍ではなく e² 倍になる。e＝1 なら同じ高さまで戻るので、式の形が正しいと分かる。' }] },
      { h: '等速円運動', t: '一定の速さで円をえがく運動を【等速円運動】といいます。速さは一定でも、速度の向きはたえず変わっているので、加速度があります。\n回る速さは【角速度 ω】(1秒あたりに回る角度、単位 rad/s)で表します。半径 r の円で角度 θ だけ回ると弧の長さは rθ なので、速さは 【v＝rω】。1周にかかる時間(周期)は 【T＝2πr/v＝2π/ω】 です。\n加速度の導き方:短い時間 Δt の間に、速度ベクトルは大きさ v のまま、角度 ωΔt だけ向きを変えます。このとき速度の変化の大きさは、およそ v×ωΔt(半径 v、中心角 ωΔt の弧の長さ)で、向きは円の中心を向きます。これを Δt で割ると、【加速度 a＝vω＝rω²＝v²/r】(中心向き)。\nこの加速度を生むには、中心向きの力が必要です。運動方程式から 【m v²/r＝F】。この中心向きの力を【向心力】といいます。向心力は新しい種類の力ではなく、糸の張力・重力・摩擦力・静電気力などが「中心向きの役」をしているものです。\n解き方:①回っている物体にはたらく力をすべてかく ②中心向きの成分の和を求める ③m v²/r(または mrω²)＝(中心向きの力の和) と書く。',
        key: '等速円運動の加速度は中心向きに v²/r＝rω²。運動方程式 m v²/r＝(中心向きの力の和)。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="等速円運動。速度は接線方向、加速度と向心力は中心向き"><circle cx="75" cy="78" r="52" class="ax"/><circle cx="75" cy="78" r="2.5" class="pt"/><line x1="75" y1="78" x2="75" y2="26" class="dash"/><circle cx="75" cy="26" r="5" class="tr"/><line x1="75" y1="26" x2="128" y2="26" class="cv"/><polyline points="121,22 128,26 121,30" class="cv"/><line x1="75" y1="31" x2="75" y2="58" class="cv2"/><polyline points="71,51 75,58 79,51" class="cv2"/><text x="62" y="92">O</text><text x="80" y="55">a</text><text x="62" y="58">r</text><text x="104" y="18">v</text><text x="140" y="60">v＝rω</text><text x="140" y="80">a＝v²/r</text><text x="140" y="100">中心向き</text><text x="140" y="120">T＝2π/ω</text></svg>',
        ex: [{ q: '質量 0.20 kg の小球を長さ 0.50 m の糸の先につけ、なめらかな水平面上で、糸の他端を中心に速さ 2.0 m/s の等速円運動をさせた。糸の張力の大きさと、周期を求めよ。(π＝3.14)', hint: '水平面上なので、中心向きの力は糸の張力だけです。', steps: ['小球にはたらく力:重力と垂直抗力(つり合う)、糸の張力 S(中心向き)。', '運動方程式:m v²/r＝S → S＝0.20×2.0²/0.50＝1.6 N。', '角速度:ω＝v/r＝2.0/0.50＝4.0 rad/s。', '周期:T＝2π/ω＝2×3.14/4.0≒1.6 s。'], a: '張力 1.6 N、周期 約 1.6 s', check: 'mrω² でも計算すると 0.20×0.50×4.0²＝1.6 N で一致する。周期は 2πr/v＝3.14/2.0≒1.6 s でも確かめられる。' }] },
      { h: '単振動', t: 'ばねにつけたおもりのように、つり合いの位置を中心に行ったり来たりする運動のうち、もっとも基本的なものを【単振動】といいます。\n単振動は【等速円運動の影】として考えると分かりやすくなります。半径 A、角速度 ω で等速円運動する点に横から光を当てると、壁にできる影は上下に動きます。その位置は 【x＝A sin ωt】 です。A を【振幅】、ω を【角振動数】といい、周期は円運動と同じ 【T＝2π/ω】。\n影の加速度は、円運動の加速度 Aω²(中心向き)の上下成分なので、【a＝−ω²x】 になります。マイナスは「いつもつり合いの位置(x＝0)に向かう」ことを表します。速さが最大になるのはつり合いの位置で、その値は Aω です。\n逆に、物体にはたらく力が 【F＝−Kx】(変位に比例し、逆向き)の形なら、ma＝−Kx より a＝−(K/m)x となり、単振動になると分かります。このとき ω＝√(K/m)、【T＝2π√(m/K)】。ばねなら K はばね定数 k です。\n【単振り子】(長さ l の糸につけたおもり)も、振れ幅が小さいとき、復元力が −(mg/l)x と近似できるので、T＝2π√(l/g) の単振動になります。周期がおもりの質量や振幅によらないこと(振り子の等時性)が特徴です。\n鉛直につるしたばねでも、つり合いの位置を中心に考えれば、周期は水平の場合と同じ 2π√(m/k) です。',
        key: '力が F＝−Kx の形なら単振動。ω＝√(K/m)、T＝2π/ω。単振動は等速円運動の影。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="単振動は等速円運動の正射影。円周上の点の高さを時間に沿って並べると正弦曲線になる"><circle cx="55" cy="75" r="40" class="ax"/><line x1="10" y1="75" x2="100" y2="75" class="dash"/><line x1="55" y1="75" x2="55" y2="35" class="dash"/><circle cx="55" cy="35" r="4" class="pt"/><line x1="55" y1="35" x2="130" y2="35" class="dash"/><line x1="110" y1="75" x2="205" y2="75" class="ax"/><line x1="110" y1="20" x2="110" y2="130" class="ax"/><path d="M110 75 Q130 -5 150 75 Q170 155 190 75" class="cv"/><circle cx="130" cy="35" r="3" class="pt"/><text x="48" y="92">O</text><text x="60" y="60">A</text><text x="114" y="16">x</text><text x="184" y="90">t</text><text x="112" y="146">x＝A sin ωt</text><text x="10" y="146">円運動の影</text></svg>',
        ex: [{ q: 'ばね定数 50 N/m のばねに質量 0.50 kg の物体をつけ、なめらかな水平面上で振幅 0.10 m の単振動をさせた。周期と、速さの最大値を求めよ。(π＝3.14)', hint: 'まず ω＝√(k/m) を求めます。', steps: ['角振動数:ω＝√(k/m)＝√(50/0.50)＝√100＝10 rad/s。', '周期:T＝2π/ω＝2×3.14/10≒0.63 s。', '速さの最大値(つり合いの位置):v＝Aω＝0.10×10＝1.0 m/s。'], a: '周期 約 0.63 s、速さの最大値 1.0 m/s', check: 'エネルギーで確かめる:端でのばねのエネルギー (1/2)×50×0.10²＝0.25 J が、中心で (1/2)×0.50×v² になるので v²＝1.0、v＝1.0 m/s で一致する。' }] },
      { h: '万有引力とケプラーの法則', t: 'すべての物体どうしは引き合っています。質量 M と m の物体が距離 r 離れているとき、その力は 【F＝GMm/r²】(G は万有引力定数で約 6.67×10⁻¹¹ N·m²/kg²)。これを【万有引力の法則】といいます。距離の2乗に反比例するのが特徴です。\n地表の重力は、地球(質量 M、半径 R)との万有引力です。mg＝GMm/R² より 【GM＝gR²】 という関係が出ます。地球の質量を知らなくても、g と R で計算できる便利な式です。\nケプラーは観測から、惑星の運動に3つの法則を見つけました。【第1法則】惑星は太陽を1つの焦点とするだ円軌道をえがく。【第2法則】太陽と惑星を結ぶ線分が一定時間に通過する面積は一定(面積速度一定)。だから太陽に近いときほど速く動きます。【第3法則】公転周期 T の2乗は、だ円軌道の半長軸 a の3乗に比例する(T²/a³＝一定)。\n第3法則は、円軌道として運動方程式から導けます。半径 r の円軌道で mr(2π/T)²＝GMm/r² とすると、【T²/r³＝4π²/(GM)】。右辺は惑星の質量 m によらないので、同じ太陽のまわりを回る惑星ではどれも同じ値になります。\n地表すれすれを回る人工衛星の速さは、m v²/R＝mg より v＝√(gR)≒7.9×10³ m/s(約 7.9 km/s)。これを【第1宇宙速度】といいます。万有引力による位置エネルギーは U＝−GMm/r(無限遠を0とする)で、遠くへ打ち上げる問題ではこちらを使います。',
        key: '万有引力 F＝GMm/r²、地表では GM＝gR²。ケプラー第3法則 T²/a³＝一定は、円運動の運動方程式から導ける。',
        ex: [{ q: '同じ星のまわりを円軌道で回る衛星Aと衛星Bがある。Bの軌道半径はAの4倍である。Bの公転周期はAの何倍か。', hint: 'ケプラーの第3法則 T²/r³＝一定 を使います。', steps: ['同じ星のまわりなので、T²/r³ は A と B で等しい。', 'T_B²/T_A²＝(r_B/r_A)³＝4³＝64。', 'T_B/T_A＝√64＝8。'], a: '8倍', check: '円運動の式 T＝2π√(r³/(GM)) で r を4倍にすると、√(4³)＝8 倍になり一致する。' }] },
      { h: 'もっと深く:保存則はどこから来るのか', t: '運動量保存の法則は、新しい法則ではなく、【作用・反作用の法則】と【運動量の変化＝力積】を組み合わせたものです。AとBがおよぼし合う力は同じ大きさで逆向き、しかも同じ時間だけはたらくので、Aが得た力積とBが得た力積は打ち消し合います。だから和が変わらないのです。\nこの見方をすると、【重心】の意味も分かります。2物体の重心の速度は v_G＝(m₁v₁＋m₂v₂)/(m₁＋m₂)、つまり「運動量の和÷質量の和」です。外力がなければ分子の運動量の和が一定なので、【重心は等速直線運動を続けます】。衝突してくっついた物体が重心の速度で進むのは、このためです。\nでは、衝突で失われる運動エネルギーはどれだけか。計算すると、失われる量は ΔK＝(1/2)・{m₁m₂/(m₁＋m₂)}・(v₁−v₂)²・(1−e²) になります。重心の運動のエネルギーは保存され、【相対運動のエネルギーだけが、(1−e²) の割合で失われる】のです。e＝1 なら失われず、e＝0(一体になる)なら相対運動の分がすべて失われます。\nたとえば、2.0 kg の物体が 3.0 m/s で静止した 1.0 kg の物体にぶつかって一体になる場合、m₁m₂/(m₁＋m₂)＝2/3 kg なので、ΔK＝(1/2)×(2/3)×3.0²×1＝3.0 J となり、運動量保存から直接計算した値と一致します。検算の道具として便利です。\nケプラーの第2法則(面積速度一定)にも、保存則がかくれています。太陽から惑星にはたらく万有引力は、いつも太陽の方向(中心向き)なので、惑星を「回す勢い」を変えません。この回す勢い(角運動量、円なら mvr)が一定であることが面積速度一定の正体です。近日点の距離 r₁・速さ v₁、遠日点の距離 r₂・速さ v₂ の間には r₁v₁＝r₂v₂ が成り立ち、太陽に近いほど速く動きます。\n保存則をまとめると、運動量は「外力がないとき」、力学的エネルギーは「保存力以外が仕事をしないとき」、面積速度は「力が中心向きのとき」に保存されます。問題を読んだら、どの条件が満たされているかを最初に確かめましょう。',
        key: '運動量保存＝作用反作用。重心の速度は外力がなければ一定。衝突で失われるのは相対運動のエネルギーだけで、その割合は (1−e²)。面積速度一定は中心力のときの保存則。' },
      { h: '入試ではこう出る:円運動とエネルギー、衝突とばね', t: '共通テストでも個別試験でも、力学は【2つの法則を組み合わせる問題】が中心です。単独の公式を覚えているかではなく、「どの場面で、どの法則を使うか」を区切れるかが問われます。\n【型1:鉛直面内の円運動】糸につけた小球や、円筒の内側をすべる小球の問題です。「最高点まで回れる条件」を問われたら、①最高点での運動方程式(中心向き:m v²/r＝T＋mg)、②最下点と最高点の力学的エネルギー保存、の2式を立てます。糸がたるまない条件は【T≧0】です。円運動の速さは一定ではないので、等速円運動の公式 T＝2πr/v は使えません。\n【型2:衝突とばね】ばねのついた物体に別の物体がぶつかる問題では、「ばねが最も縮んだ瞬間」に2物体の速度が等しくなります(相対速度が0)。このとき運動量保存で共通の速度を出し、エネルギー保存で弾性エネルギーを出します。ばねを介した衝突では、熱にならないので力学的エネルギーが保存されます。\n【型3:人工衛星と万有引力】「万有引力＝向心力」の式に加え、地表での重力 mg＝GMm/R² から【GM＝gR²】と置きかえる操作がよく出ます。G や M が与えられていなくても g と R で答えられます。\nひっかけとして多いのは、①回転する人から見た遠心力と、地上から見た向心力を両方書いてしまう、②楕円軌道で半径の代わりに半長軸を使うべきところで使わない、③一体になる衝突でエネルギー保存を使う、の3つです。\n時間配分のコツ:最初に「場面の区切り」を図に書きこむ(衝突の瞬間/その後の運動)と、立てる式の数がはっきりして迷いません。',
        key: '最高点の条件は「運動方程式＋エネルギー保存＋T≧0」。ばねが最も縮むのは速度がそろった瞬間。地表の重力から GM＝gR²。',
        ex: [{ q: '長さ 0.40 m の軽い糸の一端を固定し、他端に小球をつけた。小球が最下点にあるとき水平に速さ v₀ を与えて、鉛直面内で円運動をさせる。糸がたるまずに1回転するための v₀ の最小値を求めよ。(g＝9.8 m/s²)', hint: '最高点で糸の張力 T≧0 になる条件と、エネルギー保存を組み合わせます。', steps: ['最高点での速さを v とする。中心向き(下向き)の運動方程式は m v²/r＝T＋mg。', '糸がたるまない条件 T≧0 より、m v²/r≧mg、つまり v²≧gr。', '最下点と最高点(高さの差 2r)で力学的エネルギー保存:(1/2)mv₀²＝(1/2)mv²＋mg・2r より v₀²＝v²＋4gr。', 'v²≧gr を代入して v₀²≧5gr＝5×9.8×0.40＝19.6。', 'v₀≧√19.6≒4.4 m/s。'], a: '約 4.4 m/s(v₀＝√(5gr))', check: '4.4²＝19.36、4.43²≒19.6 なので妥当。質量 m が答えに入らないことも確認(すべての式で m が消える)。' }, { q: 'なめらかな水平面上に、左端に軽いばね(ばね定数 600 N/m)をつけた質量 3.0 kg の物体Bが静止している。左から質量 1.0 kg の小球Aが 4.0 m/s で進んできて、ばねを押した。ばねが最も縮んだときの2物体の速さと、そのときのばねの縮みを求めよ。', hint: '最も縮んだ瞬間は、AとBの速度が等しくなります。', steps: ['最も縮んだ瞬間、A と B は同じ速度 V で動く。運動量保存:1.0×4.0＝(1.0＋3.0)V より V＝1.0 m/s。', 'はじめの運動エネルギー:(1/2)×1.0×4.0²＝8.0 J。', 'このときの運動エネルギー:(1/2)×4.0×1.0²＝2.0 J。差の 6.0 J がばねの弾性エネルギー。', '(1/2)×600×x²＝6.0 より x²＝0.020、x≒0.14 m。'], a: '速さ 1.0 m/s、縮み 約 0.14 m', check: '「失われる相対運動のエネルギー」の式で、(1/2)×(1×3/4)×4.0²＝6.0 J と一致する。' }] }
    ],
    faq: [['運動量保存と力学的エネルギー保存は、どう使い分けるの?', '衝突や分裂のように、短い時間に強い力がはたらく場面では、まず【運動量保存】を使います。このとき熱や変形にエネルギーが逃げることが多いので、力学的エネルギー保存はふつう使えません(弾性衝突 e＝1 のときだけ使えます)。\n衝突の前や後で、物体が坂をすべる・ばねを縮めるなどの場面では、力学的エネルギー保存を使います。「衝突の瞬間は運動量、それ以外はエネルギー」と場面を区切るのがコツです。'],
      ['遠心力は、向心力とどうちがうの?', '遠心力は、物体と一緒に回る人(回転する座標系)から見たときに考える【見かけの力(慣性力)】で、大きさ m v²/r、外向きです。\n地上で静止している人から見るときは遠心力を考えず、「中心向きの力の和＝m v²/r」と運動方程式を書きます。回る人から見るときは遠心力を加えて「力のつり合い」として式を書きます。どちらか一方の立場を選び、混ぜないことが大切です。'],
      ['単振動の周期が振幅によらないのはなぜ?', '振幅を大きくすると、動く距離は長くなりますが、復元力も変位に比例して大きくなるので、そのぶん速く動きます。\nこの2つの効果がちょうど打ち消し合うため、周期 T＝2π√(m/K) には振幅が入りません。単振り子でこれが成り立つのは、振れ幅が小さいときだけです。'],
      ['衝突で失われた運動エネルギーは、どこへ行くの?', 'おもに、物体の変形・熱・音になります。粘土のようにつぶれる物体では、変形にともなって内部で熱になります。\nくわしく見ると、失われるのは「2物体が近づき合う相対運動」の分だけで、重心の運動のエネルギーは残ります。だから一体になっても全体は止まらず、重心の速度で進み続けます。']],
    drill: [
      { lv: 1, q: '質量 0.50 kg のボールが 6.0 m/s で壁に垂直に当たり、逆向きに 4.0 m/s ではね返った。壁から受けた力積の大きさと、壁とのはね返り係数を求めよ。', a: '力積 5.0 N·s、はね返り係数 約 0.67(2/3)', exp: 'はじめにボールが進む向きを正とします。はね返った後の速度は −4.0 m/s です。\n力積＝運動量の変化＝0.50×(−4.0)−0.50×6.0＝−5.0 N·s。大きさは 5.0 N·s で、向きははね返る向きです。符号をつけずに 6.0−4.0 と引くと 1.0 N·s というまちがいになります。\nはね返り係数は「離れる速さ÷近づく速さ」なので e＝4.0/6.0≒0.67 です。' },
      { lv: 1, q: '半径 2.0 m の円周上を、周期 4.0 s で等速円運動する物体がある。角速度・速さ・加速度の大きさを求めよ。(π＝3.14)', a: '角速度 1.57 rad/s、速さ 3.14 m/s、加速度 約 4.9 m/s²', exp: '1周(2π rad)を 4.0 s で回るので ω＝2π/T＝2×3.14/4.0＝1.57 rad/s。\n速さは v＝rω＝2.0×1.57＝3.14 m/s。円周 2πr＝12.56 m を 4.0 s で回ると考えても同じです。\n加速度は a＝rω²＝2.0×1.57²≒4.93 m/s²。v²/r＝3.14²/2.0≒4.93 と2通りで計算して一致を確かめましょう。向きは円の中心向きです。' },
      { lv: 2, q: 'なめらかな水平面上で、右向きに 5.0 m/s で進む質量 2.0 kg の物体Aと、左向きに 1.0 m/s で進む質量 3.0 kg の物体Bが正面衝突した。はね返り係数が 0.50 のとき、衝突後のAとBの速度を求めよ。', a: 'A:左向きに 0.40 m/s、B:右向きに 2.6 m/s', exp: '右向きを正とし、衝突後の速度を vA、vB とします。B のはじめの速度は −1.0 m/s です。\n運動量保存:2.0×5.0＋3.0×(−1.0)＝2.0vA＋3.0vB より 2.0vA＋3.0vB＝7.0。\nはね返り係数:vB−vA＝0.50×{5.0−(−1.0)}＝3.0。\n連立すると 2.0vA＋3.0(vA＋3.0)＝7.0 → 5.0vA＝−2.0 → vA＝−0.40 m/s、vB＝2.6 m/s。検算:2.0×(−0.40)＋3.0×2.6＝−0.8＋7.8＝7.0 で運動量が保存されています。' },
      { lv: 2, q: 'ばね定数 20 N/m の軽いばねの上端を固定し、下端に質量 0.20 kg のおもりをつるした。つり合いの位置でのばねの伸びと、このおもりを上下に振動させたときの周期を求めよ。(g＝9.8 m/s²、π＝3.14)', a: '伸び 0.098 m、周期 約 0.63 s', exp: 'つり合いでは kx₀＝mg なので x₀＝0.20×9.8/20＝0.098 m です。\n鉛直ばね振り子では、つり合いの位置からの変位 x に対して合力が −kx になります(重力は伸び x₀ の分のばねの力と打ち消し合う)。だから水平の場合と同じく T＝2π√(m/k) です。\nT＝2×3.14×√(0.20/20)＝6.28×0.10≒0.63 s。T＝2π√(x₀/g)＝2π√(0.098/9.8) としても同じ値になり、検算になります。' },
      { lv: 3, q: '地表すれすれを等速円運動する人工衛星の速さと周期を、地表の重力加速度 g と地球の半径 R を使って表し、g＝9.8 m/s²、R＝6.4×10⁶ m として数値で求めよ。(π＝3.14、空気抵抗は無視)', a: 'v＝√(gR)≒7.9×10³ m/s、T＝2π√(R/g)≒5.1×10³ s(約85分)', exp: '衛星にはたらく力は万有引力だけで、これが向心力になります:m v²/R＝GMm/R²。\n地表での重力 mg＝GMm/R² から GM＝gR²。代入すると v²＝gR、v＝√(gR)＝√(9.8×6.4×10⁶)＝√(6.272×10⁷)≒7.9×10³ m/s(第1宇宙速度)。\n周期は T＝2πR/v＝2π√(R/g)＝6.28×√(6.53×10⁵)≒6.28×808≒5.1×10³ s。約85分で地球を1周します。\nG や M が与えられていないときに GM＝gR² を使うのが、この型のポイントです。' },
      { lv: 3, q: '長さ 0.50 m の軽い糸に質量 0.10 kg の小球をつけ、糸が鉛直と 60° をなすように、水平面内で等速円運動させた(円すい振り子)。糸の張力の大きさと、回転の周期を求めよ。(g＝9.8 m/s²、π＝3.14)', a: '張力 約 2.0 N、周期 約 1.0 s', exp: '張力を S とします。小球は高さが変わらないので、鉛直方向は力のつり合い:S cos60°＝mg より S＝mg/cos60°＝0.10×9.8/0.5＝1.96≒2.0 N。\n水平方向は円運動の運動方程式です。半径は r＝L sin60° なので、S sin60°＝m(L sin60°)ω² より S＝mLω²、ω²＝S/(mL)＝g/(L cos60°)。\nT＝2π/ω＝2π√(L cos60°/g)＝6.28×√(0.25/9.8)≒6.28×0.160≒1.0 s。\n「鉛直はつり合い、水平は運動方程式」と方向で分けるのが、円すい振り子の解き方の型です。' }
    ],
    terms: [['運動量', '質量×速度(p＝mv)。向きをもつ量'], ['力積', '力×時間(FΔt)。運動量の変化に等しい'], ['はね返り係数', '離れる速さ÷近づく速さ。0≦e≦1'], ['角速度', '1秒あたりに回る角度 ω(rad/s)。v＝rω'], ['向心力', '等速円運動で中心向きにはたらく力の合力'], ['単振動', 'a＝−ω²x を満たす往復運動。等速円運動の影'], ['万有引力', 'F＝GMm/r²。すべての物体の間にはたらく引力'], ['ケプラーの第3法則', '惑星の公転周期の2乗は、半長軸の3乗に比例する']],
    miss: ['はね返る衝突で、運動量の変化を速さの差で計算する。→ 最初に正の向きを決め、逆向きの速度にはマイナスをつけてから引き算します。', 'くっつく衝突で、力学的エネルギー保存を使ってしまう。→ 衝突の瞬間は運動量保存だけ。運動エネルギーは減ると覚えておきます。', '円運動で、重力や張力とは別に「向心力」を書き加える。→ 向心力は実際の力の合力の名前です。図には実際にはたらく力だけをかきます。', 'はね返り係数の式で、マイナスを忘れたり、分母と分子を逆にしたりする。→ 「離れる速さ÷近づく速さ」と言葉で確認してから代入します。', '単振動の周期 2π√(m/k) を 2π√(k/m) と逆に覚える。→ 重いほどゆっくり振動する(周期が長い)ので、m は分子だと確かめます。'],
    sum: ['運動量 p＝mv、運動量の変化＝力積 FΔt。', '外力がなければ運動量の和は保存。衝突は運動量保存とはね返り係数の式を連立する。', '等速円運動:v＝rω、T＝2π/ω、加速度は中心向きに v²/r＝rω²。', '単振動:F＝−Kx なら a＝−ω²x、ω＝√(K/m)、T＝2π/ω。最大の速さは Aω。', '万有引力 F＝GMm/r²、GM＝gR²。ケプラー第3法則 T²/a³＝一定。'],
    next: '次は『気体と熱力学(物理)』へ。ここで使った「壁に当たってはね返る分子の運動量の変化」から、気体の圧力が説明できます。'
  };

  // ===== 気体と熱力学 =====
  L.p4_heat = {
    goal: '気体の状態方程式を使いこなし、圧力や温度を分子の運動から説明でき、熱力学第一法則で定積・定圧・等温・断熱の各変化の熱と仕事を計算できるようになる。',
    intro: '自転車の空気入れで何度も押すと、ポンプの先が熱くなります。空気を押し縮める「仕事」が、空気の温度を上げたのです。逆に、スプレー缶から勢いよくガスを出すと缶が冷たくなります。気体は、熱をもらう・仕事をする・仕事をされる、によって温度や圧力を変えます。この単元では、目に見えない分子の運動から気体の性質を説明し、エネルギーの出入りを1本の式(熱力学第一法則)で整理します。',
    pre: '【絶対温度】T〔K〕＝t〔℃〕＋273。分子の熱運動が最も小さくなる温度(−273 ℃)を0 K とします。気体の式に入れる温度は必ず絶対温度です。\n【圧力】面を垂直に押す力を、面積で割った値です。p＝F/S、単位は Pa(＝N/m²)。大気圧はおよそ 1.0×10⁵ Pa です。\n【物質量】粒子 6.0×10²³ 個(アボガドロ定数 Nᴀ)を 1 mol とします。化学基礎で学んだ量です。\n【熱量と内部エネルギー】物体の中の分子は乱雑に運動していて、その運動エネルギーなどの合計を【内部エネルギー】といいます。熱は、温度の高い物体から低い物体へ移るエネルギーです。\n【仕事】力×力の向きに動いた距離(W＝Fx)。気体がピストンを押して動かすときにも仕事をします。\n【運動量の変化＝力積】前の単元で学んだ関係です。分子が壁に当たってはね返るとき、壁が受ける力積から圧力を求めます。',
    secs: [
      { h: '気体の状態方程式', t: '気体の圧力 p、体積 V、絶対温度 T の間には、実験から次の関係が知られています。温度一定なら pV は一定(【ボイルの法則】)、圧力一定なら V は T に比例(【シャルルの法則】)。2つをまとめると 【pV/T＝一定】(ボイル・シャルルの法則)です。\nこの「一定」の値は、気体の量に比例します。1 mol あたりの値を R とすると、n mol では pV/T＝nR、つまり 【pV＝nRT】 となります。これを【理想気体の状態方程式】、R を【気体定数】(約 8.31 J/(mol·K))といいます。\n【理想気体】とは、分子の大きさと分子間の力を無視できる気体のことです。ふつうの温度・圧力の空気は、ほぼ理想気体として扱えます。\n使い方:①気体の物質量が一定なら pV/T＝一定 で、状態の前後を比べる ②具体的な量(mol や圧力の値)を求めるなら pV＝nRT を使う。\n単位をそろえることが大切です。R＝8.31 J/(mol·K) を使うときは、p は Pa、V は m³(1 L＝1.0×10⁻³ m³)、T は K にします。',
        key: 'pV＝nRT。温度は絶対温度、体積は m³、圧力は Pa にそろえる。',
        ex: [{ q: '圧力 1.0×10⁵ Pa、温度 27 ℃、体積 3.0 L の気体を、温度 127 ℃、体積 2.0 L にした。圧力はいくらになるか。', hint: '物質量は変わらないので pV/T＝一定 を使います。温度は K に直します。', steps: ['絶対温度:27 ℃→300 K、127 ℃→400 K。', 'ボイル・シャルルの法則:1.0×10⁵×3.0/300＝p×2.0/400。', 'p＝1.0×10⁵×(3.0/2.0)×(400/300)。', '＝1.0×10⁵×1.5×(4/3)＝2.0×10⁵ Pa。'], a: '2.0×10⁵ Pa', check: '体積が小さくなる(圧力↑)、温度が上がる(圧力↑)の両方で圧力は増えるはずで、2倍になっているので向きが合っている。比の式なので L のままでよい。' }] },
      { h: '気体分子運動論:圧力の正体', t: '気体の圧力は、たくさんの分子が壁に当たってはね返るときの力積から生まれます。これを計算で確かめるのが【気体分子運動論】です。\n一辺 L の立方体の容器に、質量 m の分子が N 個入っているとします。1個の分子が x 方向の速度成分 vₓ で壁に垂直に弾性衝突すると、分子の運動量は mvₓ から −mvₓ に変わります。分子が壁から受けた力積は −2mvₓ なので、【壁が受ける力積は 2mvₓ】 です。\nこの分子は、往復 2L 進むごとに同じ壁に当たるので、1秒あたりの衝突回数は vₓ/(2L)。だから壁が1秒に受ける力積、つまり平均の力は 2mvₓ×vₓ/(2L)＝mvₓ²/L です。\nN 個分を足すと F＝Nm(vₓ²の平均)/L。分子はどの向きにも同じように動くので、vₓ² の平均は v² の平均の 1/3。圧力は F/L² で、L³＝V なので、【p＝Nm(v²の平均)/(3V)】 となります。\nこの式を pV＝nRT と比べます。N＝nNᴀ、k＝R/Nᴀ(【ボルツマン定数】約 1.38×10⁻²³ J/K)とおくと、【(1/2)m(v²の平均)＝(3/2)kT】。つまり【絶対温度は、分子1個の平均の運動エネルギーに比例する】ことが分かります。温度とは、分子の運動の激しさのことなのです。\n分子の速さの目安(二乗平均速度)は √(3RT/M)(M はモル質量〔kg/mol〕)です。同じ温度なら、軽い分子ほど速く動きます。',
        key: '圧力は分子の衝突による力積から生まれる。分子1個の平均運動エネルギーは (3/2)kT で、絶対温度に比例する。',
        ex: [{ q: '温度 300 K のヘリウム(モル質量 4.0×10⁻³ kg/mol)の二乗平均速度を求めよ。(R＝8.3 J/(mol·K))', hint: '√(3RT/M) に代入します。M は kg/mol の単位にします。', steps: ['3RT＝3×8.3×300＝7470。', '3RT/M＝7470/(4.0×10⁻³)≒1.87×10⁶ m²/s²。', '√(1.87×10⁶)≒1.4×10³ m/s。'], a: '約 1.4×10³ m/s', check: '単位:J/kg＝(kg·m²/s²)/kg＝m²/s² なので、ルートをとると m/s になる。音速(約 340 m/s)より速いが、軽い分子なので妥当な大きさ。' }] },
      { h: '内部エネルギー', t: '気体の【内部エネルギー U】は、すべての分子の運動エネルギーなどの合計です。理想気体では分子間の力を考えないので、位置エネルギーは入りません。\n【単原子分子】(ヘリウム・ネオン・アルゴンのように原子1個で分子になっているもの)の理想気体では、分子1個の平均運動エネルギー (3/2)kT を N 個分足して、U＝(3/2)NkT＝【(3/2)nRT】 です。\nこの式から、【理想気体の内部エネルギーは温度だけで決まる】ことが分かります。圧力や体積が変わっても、温度が同じなら U は同じです。\n温度変化 ΔT のときの変化は 【ΔU＝(3/2)nRΔT】(単原子分子)。温度が上がれば ΔU＞0、下がれば ΔU＜0、等温なら ΔU＝0 です。\n酸素や窒素のような2原子分子は、分子の回転のエネルギーも加わるので、常温ではおよそ (5/2)nRT になります。問題文で「単原子分子」と書かれているかを確かめましょう。',
        key: '理想気体の内部エネルギーは温度だけで決まる。単原子分子なら U＝(3/2)nRT。' },
      { h: '熱力学第一法則と気体の仕事', t: '気体の内部エネルギーを増やす方法は2つあります。熱を加えることと、外から仕事をすることです。これをまとめたのが【熱力学第一法則】【ΔU＝Q＋W】 です。Q は気体が吸収した熱量、W は気体が【外からされた】仕事です。\nこれはエネルギー保存の法則そのものです。熱で入ったエネルギーと仕事で入ったエネルギーの合計が、内部エネルギーの増加になります。気体が熱を放出すれば Q＜0、気体が外へ仕事をすれば W＜0 です。\n気体が外に【した】仕事 W′ も使います(W′＝−W)。圧力 p の気体が、断面積 S のピストンを Δx だけ押し出すと、力は pS なので仕事は pS×Δx＝【pΔV】(ΔV は体積の増加)です。このとき第一法則は Q＝ΔU＋W′ とも書けます。「もらった熱は、内部エネルギーの増加と、外にした仕事に分かれる」と読みます。\n圧力が変わるときも、【p-V 図の下の面積が、気体がした仕事】になります。膨張なら W′＞0、圧縮なら W′＜0 です。同じ始点と終点でも、途中の道すじがちがえば仕事はちがいます。\n符号のミスを防ぐには、毎回「Q は吸収が正」「W はされたら正」「W′ はしたら正」と書き出してから式を立てます。',
        key: 'ΔU＝Q＋W(W はされた仕事)。気体がした仕事 W′ は p-V 図の面積で、定圧なら pΔV。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="p-V図。定圧で膨張するとき、グラフの下の長方形の面積が気体のした仕事 pΔV"><rect x="60" y="55" width="110" height="70" class="fl"/><line x1="30" y1="125" x2="205" y2="125" class="ax"/><line x1="30" y1="125" x2="30" y2="12" class="ax"/><line x1="60" y1="55" x2="170" y2="55" class="cv"/><polyline points="112,51 120,55 112,59" class="cv"/><line x1="60" y1="55" x2="60" y2="125" class="dash"/><line x1="170" y1="55" x2="170" y2="125" class="dash"/><circle cx="60" cy="55" r="3" class="pt"/><circle cx="170" cy="55" r="3" class="pt"/><text x="52" y="47">A</text><text x="166" y="47">B</text><text x="16" y="59">p</text><text x="36" y="20">p</text><text x="184" y="140">V</text><text x="54" y="140">V₁</text><text x="164" y="140">V₂</text><text x="72" y="88">面積＝pΔV</text><text x="72" y="106">気体がした仕事</text></svg>',
        ex: [{ q: '単原子分子の理想気体 1.0 mol を、圧力を一定に保ったまま 300 K から 400 K まで温めた。気体がした仕事 W′、内部エネルギーの変化 ΔU、吸収した熱量 Q を求めよ。(R＝8.3 J/(mol·K))', hint: '定圧なら W′＝pΔV＝nRΔT です(pV＝nRT の変化分)。', steps: ['定圧なので W′＝pΔV。状態方程式から pΔV＝nRΔT＝1.0×8.3×100＝830 J。', 'ΔU＝(3/2)nRΔT＝1.5×830＝1245 J(約 1.2×10³ J)。', '第一法則 Q＝ΔU＋W′＝1245＋830＝2075 J(約 2.1×10³ J)。', 'まとめると Q＝(5/2)nRΔT になっている。'], a: 'W′＝830 J(約 8.3×10² J)、ΔU 約 1.2×10³ J、Q 約 2.1×10³ J', check: 'もらった熱 2075 J のうち、約 6 割が内部エネルギー、約 4 割が外への仕事になった。3/2 と 1 の比(3:2)になっていて筋が通る。' }] },
      { h: '4つの状態変化', t: '気体の変化のうち代表的な4つを、Q・W・ΔU のどれが0になるかで整理します(以下、単原子分子の理想気体)。\n【定積変化】(体積一定):体積が変わらないので W＝0。Q＝ΔU＝(3/2)nRΔT。1 mol を 1 K 上げる熱量(【定積モル比熱】)は Cᵥ＝(3/2)R です。\n【定圧変化】(圧力一定):W′＝pΔV＝nRΔT。Q＝ΔU＋W′＝(5/2)nRΔT。【定圧モル比熱】は Cₚ＝(5/2)R で、Cₚ＝Cᵥ＋R(【マイヤーの関係】)が成り立ちます。外への仕事の分だけ、定圧のほうが多くの熱が必要なのです。\n【等温変化】(温度一定):ΔU＝0 なので Q＝W′。もらった熱はすべて外への仕事になります。p-V 図では pV＝一定 の双曲線です。\n【断熱変化】(熱の出入りなし):Q＝0 なので ΔU＝W。外から仕事をされる(断熱圧縮)と温度が上がり、外へ仕事をする(断熱膨張)と温度が下がります。空気入れが熱くなるのも、上昇する空気が冷えて雲ができるのも、このためです。\np-V 図で同じ点から膨張させると、断熱変化の曲線は等温変化の曲線より急に下がります。断熱膨張では温度も下がるので、そのぶん圧力が余計に下がるからです(参考:断熱変化では pV^γ＝一定、単原子分子で γ＝5/3)。',
        key: '定積 W＝0、等温 ΔU＝0、断熱 Q＝0。定圧では Q＝(5/2)nRΔT(単原子分子)。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="p-V図の等温変化と断熱変化。同じ点から膨張すると断熱変化の曲線のほうが急に下がる"><line x1="30" y1="125" x2="205" y2="125" class="ax"/><line x1="30" y1="125" x2="30" y2="10" class="ax"/><path d="M50 22 Q70 95 195 100" class="cv"/><path d="M50 22 Q62 112 195 116" class="cv2"/><circle cx="50" cy="22" r="3" class="pt"/><text x="16" y="20">p</text><text x="184" y="140">V</text><text x="96" y="40">青線:等温 ΔU＝0</text><text x="96" y="56">赤線:断熱 Q＝0</text></svg>',
        ex: [{ q: '単原子分子の理想気体 2.0 mol を断熱圧縮したところ、外から 500 J の仕事をされた。内部エネルギーの変化と、温度の変化を求めよ。(R＝8.3 J/(mol·K))', hint: '断熱なので Q＝0。第一法則 ΔU＝Q＋W に入れます。', steps: ['断熱なので Q＝0。された仕事 W＝＋500 J。', 'ΔU＝0＋500＝500 J(内部エネルギーが増える)。', 'ΔU＝(3/2)nRΔT より ΔT＝500/(1.5×2.0×8.3)＝500/24.9。', 'ΔT≒20 K(温度が約 20 K 上がる)。'], a: 'ΔU＝＋500 J、温度は約 20 K 上がる', check: '断熱圧縮で温度が上がる、という定性的な結論と一致している。ΔT の単位は K だが、温度差なので ℃ でも同じ 20 度になる。' }] },
      { h: '熱機関と熱効率', t: '熱を受け取って仕事をし、もとの状態にもどることをくり返す装置を【熱機関】といいます(エンジンや蒸気機関)。p-V 図では、1周して始点にもどる閉じた曲線(サイクル)になります。\n1サイクルでは温度がもとにもどるので ΔU＝0。だから第一法則より、【1サイクルで外にした正味の仕事＝吸収した熱−放出した熱】です。p-V 図では、サイクルが囲む面積が正味の仕事になります(時計回りなら正)。\n【熱効率】e は、吸収した熱 Q₁ のうち何割を仕事にできたかを表します。【e＝W′/Q₁＝(Q₁−Q₂)/Q₁】(Q₂ は放出した熱)。\n熱機関は、必ず一部の熱を低温の側に捨てなければなりません(Q₂＞0)。だから熱効率は 1(100 %)にはなりません。これは【熱力学第二法則】の表れで、「熱は自然には低温から高温へ移らない」「熱をすべて仕事に変えることはできない」などと表現されます。\nこのように、もとにもどらない変化(熱の移動、摩擦による発熱、気体の拡散など)を【不可逆変化】といいます。',
        key: '1サイクルで ΔU＝0、正味の仕事＝吸収した熱−放出した熱。熱効率 e＝W′/Q₁ は必ず 1 より小さい。',
        ex: [{ q: 'ある熱機関は、1サイクルの間に高温の熱源から 1.0×10³ J の熱を吸収し、低温の熱源に 6.0×10² J の熱を放出する。1サイクルでする仕事と熱効率を求めよ。', hint: '1サイクルでは内部エネルギーはもとにもどります。', steps: ['1サイクルで ΔU＝0 なので、正味の仕事 W′＝Q₁−Q₂。', 'W′＝1.0×10³−6.0×10²＝4.0×10² J。', '熱効率 e＝W′/Q₁＝400/1000＝0.40(40 %)。'], a: '仕事 4.0×10² J、熱効率 0.40(40 %)', check: 'e は 0 と 1 の間に入っている。放出した熱の割合 600/1000＝0.60 と足して 1 になることでも確かめられる。' }] },
      { h: 'もっと深く:モル比熱の値は分子の形で決まる', t: '単原子分子の理想気体で Cᵥ＝(3/2)R になるのは、気体分子運動論から内部エネルギーが U＝(3/2)nRT と導かれるからです。分子1個の平均の運動エネルギーは (1/2)m⟨v²⟩＝(3/2)kT で、この「3」は分子が x・y・z の3方向に動けることから来ています。1方向あたり (1/2)kT ずつエネルギーが分けられている、と考えることができます(エネルギー等分配則)。\n酸素や窒素のような【二原子分子】は、3方向に飛び回るだけでなく、分子の軸のまわりではない2つの方向に【回転】もできます。そのぶんエネルギーをためこむ「入れ物」が2つ増えるので、常温では U＝(5/2)nRT、Cᵥ＝(5/2)R、Cₚ＝(7/2)R になります。同じ温度上昇でも、二原子分子の方が多くの熱を必要とするのです。\nどんな理想気体でも【Cₚ−Cᵥ＝R】(マイヤーの関係)が成り立ちます。定圧では、温度を1 K 上げる間に気体が外にする仕事が pΔV＝nRΔT＝R(1 mol あたり)だけ余分にかかるからです。比熱比 γ＝Cₚ/Cᵥ は単原子で 5/3、二原子で 7/5 です。\n断熱変化で pV^γ＝一定 となり、p-V 図で【断熱線が等温線より急】になるのも、この γ が 1 より大きいからです。断熱膨張では、気体は外へ仕事をしながら熱を受け取れないので、内部エネルギーが減って温度が下がります。温度が下がるぶん、等温のときより圧力が余計に下がるのです。\n熱機関の効率には上限があります。高温 T₁ と低温 T₂ の2つの熱源の間ではたらく熱機関の効率は、どんなに工夫しても 1−T₂/T₁ をこえられません(カルノー効率、発展)。たとえば 600 K と 300 K の間では最大 50% です。これは熱力学第二法則から導かれる結論です。',
        key: '単原子 Cᵥ＝(3/2)R、二原子(常温)Cᵥ＝(5/2)R。どの理想気体でも Cₚ−Cᵥ＝R。断熱線は等温線より急。' },
      { h: '入試ではこう出る:p-V グラフのサイクルとピストン', t: '熱力学の入試問題の大半は、【p-V グラフ上のサイクル】か【ピストンつきシリンダー】のどちらかです。どちらも、使う道具は状態方程式 pV＝nRT と第一法則 ΔU＝Q＋W(W は気体がされた仕事)の2つだけです。\n【型1:サイクル】各過程ごとに「W′(気体がした仕事)・ΔU・Q」の表を作るのが鉄則です。W′ は p-V グラフの下の面積(体積が増えれば正、減れば負)、ΔU は (3/2)nRΔT＝(3/2)Δ(pV)(単原子)、Q は Q＝ΔU＋W′ で求めます。1サイクルで ΔU の合計は 0、W′ の合計はグラフで囲まれた面積です。\n【ひっかけ】熱効率 e＝W′/Q₁ の Q₁ は、【熱を吸収した過程の Q だけを足したもの】です。放出した熱を差し引いた「正味の熱」で割るとまちがいになります(正味の熱は W′ と同じなので、効率が 1 になってしまいます)。\n【型2:ピストン】ピストンがなめらかに動いて静止しているなら、気体の圧力は【ピストンにはたらく力のつり合い】で決まります。鉛直に置いたシリンダーでは p＝p₀＋Mg/S(大気圧＋ピストンの重さ÷断面積)です。ゆっくり加熱すると、この圧力のまま膨張する定圧変化になります。\n時間配分のコツ:表を作れば、検算として「Q の合計＝W′ の合計」「ΔU の合計＝0」がすぐ確かめられます。最後の1分でこの2つを見直しましょう。',
        key: 'サイクルは過程ごとに W′・ΔU・Q の表を作る。熱効率の分母は「吸収した熱の合計」だけ。ピストンの圧力は力のつり合いで決まる。',
        ex: [{ q: '単原子分子の理想気体を、状態A(p₀, V₀)→B(2p₀, V₀)→C(2p₀, 2V₀)→D(p₀, 2V₀)→A の順に変化させた(AB・CD は定積、BC・DA は定圧)。各過程で吸収する熱 Q を p₀V₀ を使って表し、この熱機関の熱効率を求めよ。', hint: '単原子分子では ΔU＝(3/2)Δ(pV) です。各過程の W′ と ΔU を出して Q＝ΔU＋W′ とします。', steps: ['A→B(定積):W′＝0、ΔU＝(3/2)(2p₀V₀−p₀V₀)＝1.5p₀V₀、Q＝＋1.5p₀V₀。', 'B→C(定圧):W′＝2p₀×V₀＝2p₀V₀、ΔU＝(3/2)(4p₀V₀−2p₀V₀)＝3p₀V₀、Q＝＋5p₀V₀。', 'C→D(定積):W′＝0、ΔU＝(3/2)(2p₀V₀−4p₀V₀)＝−3p₀V₀、Q＝−3p₀V₀。D→A(定圧):W′＝−p₀V₀、ΔU＝−1.5p₀V₀、Q＝−2.5p₀V₀。', '正味の仕事 W′＝2p₀V₀−p₀V₀＝p₀V₀(長方形の面積)。吸収した熱 Q₁＝1.5＋5＝6.5p₀V₀。', '熱効率 e＝p₀V₀/(6.5p₀V₀)＝2/13≒0.15。'], a: 'Q:A→B ＋1.5p₀V₀、B→C ＋5p₀V₀、C→D −3p₀V₀、D→A −2.5p₀V₀。熱効率 2/13(約 15%)', check: 'Q の合計＝1.5＋5−3−2.5＝1＝W′ の合計、ΔU の合計＝1.5＋3−3−1.5＝0 で、どちらも成り立つ。' }, { q: '断面積 2.0×10⁻³ m² のシリンダーを鉛直に立て、質量 4.0 kg のなめらかに動くピストンで単原子分子の理想気体を閉じこめた。大気圧は 1.0×10⁵ Pa である。気体をゆっくり加熱したらピストンが 0.10 m 上がった。気体の圧力、気体がした仕事、吸収した熱量を求めよ。(g＝9.8 m/s²)', hint: 'ピストンのつり合いで圧力が決まり、加熱中は一定です。', steps: ['ピストンのつり合い:pS＝p₀S＋Mg より p＝1.0×10⁵＋(4.0×9.8)/(2.0×10⁻³)＝1.0×10⁵＋1.96×10⁴≒1.2×10⁵ Pa。', '定圧変化なので、W′＝pΔV＝1.196×10⁵×(2.0×10⁻³×0.10)≒24 J。', '単原子分子では ΔU＝(3/2)pΔV＝(3/2)×24≒36 J。', 'Q＝ΔU＋W′＝(5/2)pΔV≒60 J。'], a: '圧力 約 1.2×10⁵ Pa、仕事 約 24 J、熱量 約 60 J', check: '定圧で Q＝nCₚΔT＝(5/2)nRΔT＝(5/2)pΔV となり、Q:W′＝5:2 になっている。' }] }
    ],
    faq: [['同じ温度変化なのに、定積と定圧で必要な熱がちがうのはなぜ?', '内部エネルギーの変化 ΔU は温度変化だけで決まるので、どちらも同じです。\nちがうのは仕事です。定圧で温めると気体は膨張して外に仕事をするので、その分のエネルギーも熱で補わなければなりません。だから定圧のほうが nRΔT だけ多くの熱が必要になります(Cₚ＝Cᵥ＋R)。'],
      ['等温変化なのに熱を吸収するのはなぜ? 温度が上がらないのに?', '等温膨張では、気体は外に仕事をしてエネルギーを失います。そのままでは温度が下がってしまうので、同じ量の熱を外からもらって温度を保っているのです。\n熱は「温度を上げるため」だけでなく「仕事をするため」にも使われる、と考えると納得できます。'],
      ['熱力学第一法則の W の符号が、教科書や問題集によってちがうのはなぜ?', '「気体がされた仕事」を W とする書き方(ΔU＝Q＋W)と、「気体がした仕事」を W とする書き方(ΔU＝Q−W)の両方があるからです。どちらも内容は同じです。\n問題を解くときは、自分がどちらの意味で使っているかを最初に書き、途中で混ぜないようにしましょう。'],
      ['熱効率を 100% にできないのはなぜ?', '熱機関は、高温の熱源から熱を受け取り、その一部を仕事に変え、残りを低温の熱源に捨てることでサイクルをくり返します。捨てる熱を0にすると、気体を元の状態に戻せず、サイクルが続きません。\nこれは「熱をすべて仕事に変え続ける装置はつくれない」という熱力学第二法則の内容です。理想的な機関でも効率は 1−T₂/T₁ が上限です。']],
    drill: [
      { lv: 1, q: '体積を一定に保ったまま、理想気体の温度を 27 ℃ から 177 ℃ に上げた。圧力は何倍になるか。', a: '1.5 倍', exp: '体積一定なら p/T＝一定です。温度は必ず絶対温度に直します。\n27 ℃＝300 K、177 ℃＝450 K なので、圧力は 450/300＝1.5 倍です。\nセ氏温度のまま 177/27 とすると約 6.6 倍というまちがいになります。' },
      { lv: 1, q: '気体に 300 J の熱を加えたところ、気体は外部に 120 J の仕事をした。気体の内部エネルギーの変化を求めよ。また、理想気体の温度は上がったか下がったか。', a: '内部エネルギーは 180 J 増加。温度は上がった。', exp: '第一法則 ΔU＝Q＋W で、W は「気体がされた仕事」です。気体が外へ 120 J の仕事をしたので W＝−120 J。\nΔU＝300＋(−120)＝180 J。\n理想気体の内部エネルギーは温度だけで決まり、ΔU＞0 なら温度が上がります。' },
      { lv: 2, q: '単原子分子の理想気体 2.0 mol の温度を 50 K 上げるのに必要な熱量を、(1)体積一定の場合 (2)圧力一定の場合 について求めよ。(R＝8.3 J/(mol·K))', a: '(1) 約 1.2×10³ J (2) 約 2.1×10³ J', exp: '(1) 定積モル比熱 Cᵥ＝(3/2)R を使って Q＝nCᵥΔT＝2.0×1.5×8.3×50＝1245≒1.2×10³ J。\n(2) 定圧モル比熱 Cₚ＝(5/2)R を使って Q＝2.0×2.5×8.3×50＝2075≒2.1×10³ J。\n差の 830 J は、定圧のときに気体が外へした仕事 nRΔT＝2.0×8.3×50 です。ΔU はどちらも同じ 1245 J になることも確かめましょう。' },
      { lv: 2, q: '理想気体をゆっくり等温膨張させたところ、気体は 400 J の熱を吸収した。気体がした仕事と内部エネルギーの変化を答えよ。次に、別の場合として、同じ気体を断熱膨張させて外部に 400 J の仕事をさせた。内部エネルギーの変化と、温度の変化の向きを答えよ。', a: '等温:仕事 400 J、ΔU＝0。断熱:ΔU＝−400 J、温度は下がる。', exp: '等温変化では温度が変わらないので、理想気体の ΔU＝0 です。第一法則より、吸収した熱 400 J がすべて外への仕事になります。\n断熱変化では Q＝0 です。外へ 400 J の仕事をしたので W＝−400 J、ΔU＝0＋(−400)＝−400 J。\n内部エネルギーが減ったので温度は下がります。同じ「膨張して 400 J の仕事」でも、熱を受け取れるかどうかで温度変化がちがう点が大切です。' },
      { lv: 3, q: '温度 300 K の酸素分子(モル質量 3.2×10⁻² kg/mol)の二乗平均速度 √⟨v²⟩ を求めよ。また、絶対温度を 4 倍の 1200 K にすると何倍になるか。(R＝8.3 J/(mol·K))', a: '約 4.8×10² m/s。2 倍になる。', exp: '分子運動論より (1/2)m⟨v²⟩＝(3/2)kT。両辺をアボガドロ定数倍すると M⟨v²⟩＝3RT(M はモル質量〔kg/mol〕)。\n√⟨v²⟩＝√(3RT/M)＝√(3×8.3×300/0.032)＝√(2.33×10⁵)≒4.8×10² m/s。モル質量を g/mol のまま 32 とすると、値が √1000 倍ずれるので注意します。\n√⟨v²⟩ は √T に比例するので、T が 4 倍なら √4＝2 倍です。' },
      { lv: 3, q: '単原子分子の理想気体を、A(p₀, V₀)→B(3p₀, V₀)→C(3p₀, 2V₀)→D(p₀, 2V₀)→A の順に変化させた(AB・CD は定積、BC・DA は定圧)。1サイクルで気体がする正味の仕事と、熱効率を求めよ。', a: '正味の仕事 2p₀V₀、熱効率 4/21(約 19%)', exp: '正味の仕事はグラフで囲まれた長方形の面積で、(3p₀−p₀)×(2V₀−V₀)＝2p₀V₀ です。\n熱を吸収するのは温度が上がる A→B と B→C です。A→B:Q＝ΔU＝(3/2)(3p₀V₀−p₀V₀)＝3p₀V₀。B→C:W′＝3p₀V₀、ΔU＝(3/2)(6p₀V₀−3p₀V₀)＝4.5p₀V₀、Q＝7.5p₀V₀。合計 Q₁＝10.5p₀V₀。\n熱効率 e＝2p₀V₀/10.5p₀V₀＝4/21≒0.19。\n検算:C→D で Q＝−6p₀V₀、D→A で Q＝−2.5p₀V₀。Q の合計＝10.5−8.5＝2p₀V₀ が正味の仕事と一致します。' }
    ],
    terms: [['理想気体', '分子の大きさと分子間力を無視できる気体。pV＝nRT に従う'], ['気体定数', 'R≒8.31 J/(mol·K)'], ['ボルツマン定数', 'k＝R/Nᴀ≒1.38×10⁻²³ J/K'], ['内部エネルギー', '分子の運動エネルギーなどの総和。理想気体では温度だけで決まる'], ['熱力学第一法則', 'ΔU＝Q＋W。熱と仕事をふくむエネルギー保存'], ['モル比熱', '1 mol の温度を 1 K 上げる熱量。単原子分子で Cᵥ＝(3/2)R、Cₚ＝(5/2)R'], ['断熱変化', '熱の出入りがない変化。Q＝0'], ['熱効率', '吸収した熱のうち仕事になった割合 e＝W′/Q₁']],
    miss: ['温度を ℃ のまま pV＝nRT に入れる。→ 気体の式では必ず 273 を足して K にします。最初に温度を全部 K に直してから式を立てます。', '「された仕事」と「した仕事」の符号を混同する。→ 式を書く前に「W はされた仕事(圧縮で正)」と言葉で書いておきます。', '等温変化では Q＝0 だと思いこむ。→ 等温で0になるのは ΔU です。Q＝0 は断熱変化。表で区別して覚えます。', '定積変化でも pΔV の仕事を計算してしまう。→ 体積が変わらなければピストンは動かないので、仕事は0です。', '単原子分子でない気体に (3/2)nRT を使う。→ 問題文の「単原子分子」の指定を確かめ、指定がなければ与えられたモル比熱を使います。'],
    sum: ['pV＝nRT(T は絶対温度)。物質量一定なら pV/T＝一定。', '圧力は分子の衝突による力積から生まれ、(1/2)m(v²の平均)＝(3/2)kT。', '単原子分子の理想気体の内部エネルギー U＝(3/2)nRT。温度だけで決まる。', '熱力学第一法則 ΔU＝Q＋W。気体がした仕事は p-V 図の面積。', '定積 W＝0、定圧 Q＝(5/2)nRΔT、等温 ΔU＝0、断熱 Q＝0。', '熱効率 e＝W′/Q₁ は必ず 1 より小さい(熱力学第二法則)。'],
    next: '次は『波動:波の式・ドップラー効果・光の干渉(物理)』へ。ここで学んだ分子の運動は、音(空気の振動)が伝わるしくみにもつながっています。'
  };

  // ===== 波動 =====
  L.p4_wave = {
    goal: '波を式で表して読み取り、ドップラー効果の振動数を求め、ヤングの実験・回折格子・薄膜の干渉の条件を「経路差(光路差)」から自分で導けるようになる。',
    intro: 'シャボン玉が虹色に光るのは、色がついているからではありません。薄い膜の表と裏で反射した2つの光が重なり、ある色は強め合い、ある色は打ち消し合っているのです。救急車のサイレンが通り過ぎると急に低く聞こえるのも、波の性質です。この単元では、波を式で表す方法と、「2つの波の道のりの差が波長の何倍か」で強め合い・弱め合いが決まるという、干渉の考え方を身につけます。',
    pre: '【波の基本量】振幅 A(ゆれの大きさ)、波長 λ(山から次の山までの長さ)、周期 T(1回振動する時間)、振動数 f(1秒あたりの振動の回数)。f＝1/T、波の速さ v＝fλ＝λ/T です。\n【波の重ね合わせ】2つの波が重なると、変位はそれぞれの変位の和になります。山と山が重なれば強め合い、山と谷が重なれば弱め合います。\n【反射と位相】固定端で反射すると波は上下が逆になり(位相が π ずれる)、自由端ではそのまま反射します。光の反射でもこの考え方を使います。\n【屈折率】光の速さは物質中で遅くなります。真空中の速さ c と物質中の速さ v の比 n＝c/v を屈折率といいます。水は約 1.33、ガラスは約 1.5 です。\n【三角比と近似】角度 θ が小さいとき、sinθ≒tanθ と近似できます。干渉の式を簡単にするときに使います。',
    secs: [
      { h: '波を式で表す', t: '波の形は時間とともに動いていきます。ある位置 x、ある時刻 t での変位 y を1つの式で表せると、波のようすがすべて分かります。\n導き方:原点の媒質が y＝A sin(2πt/T) で振動しているとします。波が x 軸の正の向きに速さ v で進むと、位置 x の点は原点より x/v だけ【遅れて】同じ振動をします。だから、時刻 t の位置 x の変位は、原点の時刻 t−x/v の変位と同じです。\ny＝A sin{(2π/T)(t−x/v)}。vT＝λ を使って整理すると、【y＝A sin 2π(t/T−x/λ)】 になります。\n負の向きに進む波なら、位置 x の点は原点より「先に」振動するので、t−x/v の代わりに t＋x/v となり、y＝A sin 2π(t/T＋x/λ) です。\n式の読み方:sin の中の t の係数から周期 T、x の係数から波長 λ が分かります。そこから f＝1/T、v＝λ/T も求められます。\nなお、原点の振動のしかた(t＝0 で y＝0 から上がるか、など)によって、cos を使ったりマイナスがついたりします。式を丸暗記するより、「x/v だけ遅れる」という考え方で毎回作れるようにしましょう。',
        key: '位置 x の点は原点より x/v 遅れて振動する → y＝A sin 2π(t/T−x/λ)(正の向きに進む波)。',
        ex: [{ q: '波が y＝0.20 sin 2π(t/0.50−x/4.0)〔m〕で表される(t は秒、x はメートル)。振幅・周期・波長・振動数・速さと、進む向きを答えよ。', hint: 'y＝A sin 2π(t/T−x/λ) と見比べます。', steps: ['振幅 A＝0.20 m。', 't/T と t/0.50 を比べて T＝0.50 s、x/λ と x/4.0 を比べて λ＝4.0 m。', '振動数 f＝1/T＝2.0 Hz。速さ v＝λ/T＝4.0/0.50＝8.0 m/s。', '符号が t−x の形なので、x 軸の正の向きに進む。'], a: '振幅 0.20 m、周期 0.50 s、波長 4.0 m、振動数 2.0 Hz、速さ 8.0 m/s、x 軸の正の向き', check: 'v＝fλ＝2.0×4.0＝8.0 m/s でも一致する。' }] },
      { h: 'ドップラー効果', t: '音源や観測者が動くと、聞こえる音の振動数が変わります。これを【ドップラー効果】といいます。\n音源が動く場合:振動数 f の音源が、音速 V の空気中を速さ vₛ で観測者に近づくとします。1秒間に出した f 個の波は、音源の前方では長さ V−vₛ の中につまります(音は1秒で V 進むが、音源も vₛ 進むから)。だから前方の波長は 【λ′＝(V−vₛ)/f】 と短くなります。後方では (V＋vₛ)/f と長くなります。\n観測者が動く場合:観測者が速さ v₀ で音源から遠ざかると、観測者から見た音の速さは V−v₀ になります。1秒間に受け取る波の数は (V−v₀)/λ′ です。\n2つをまとめると、【f′＝(V−v₀)/(V−vₛ)×f】。ただし速度 v₀・vₛ は「音源から観測者へ向かう向き」を正とします。音源が近づく(vₛ＞0)と分母が小さくなり f′ は大きく、観測者が近づく(v₀＜0)と分子が大きくなり f′ は大きくなります。\n大事なのは、【音源が動くと波長が変わり、観測者が動くと波長は変わらず受け取る回数が変わる】という区別です。風が吹いているときは、音速 V を風の分だけ増減させて考えます。',
        key: 'f′＝(V−v₀)/(V−vₛ)×f(音源→観測者の向きが正)。音源が動くと波長が変わる。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="右へ動く音源から出た波面。前方では波面の間隔(波長)がつまり、後方では広がる"><circle cx="76" cy="75" r="54" class="ax"/><circle cx="82" cy="75" r="39" class="ax"/><circle cx="88" cy="75" r="24" class="ax"/><circle cx="94" cy="75" r="9" class="ax"/><circle cx="100" cy="75" r="4" class="pt"/><line x1="100" y1="75" x2="128" y2="75" class="cv2"/><polyline points="121,71 128,75 121,79" class="cv2"/><text x="104" y="68">vₛ</text><text x="146" y="70">前方</text><text x="146" y="86">λ が短い</text><text x="4" y="144">後方:λ が長い</text><text x="120" y="144">前方:音が高い</text></svg>',
        ex: [{ q: '振動数 640 Hz の音を出す救急車が、20 m/s で静止している人に近づき、通り過ぎて遠ざかっていく。近づくときと遠ざかるときに聞こえる振動数を求めよ。(音速 340 m/s)', hint: '近づくときは vₛ＝＋20、遠ざかるときは vₛ＝−20(音源→観測者の向きが正)。', steps: ['観測者は静止しているので v₀＝0。', '近づくとき:f′＝340/(340−20)×640＝340/320×640＝680 Hz。', '遠ざかるとき:f″＝340/(340＋20)×640＝340/360×640≒604 Hz。', '有効数字2けたなら 6.8×10² Hz と 6.0×10² Hz。'], a: '近づくとき 680 Hz、遠ざかるとき 約 604 Hz', check: '近づくと高く、遠ざかると低くなっていて、経験と一致する。音源の速さが音速よりずっと小さいので、変化はもとの1割以内で妥当。' }] },
      { h: 'ヤングの実験:2つのスリットによる干渉', t: '光が波であることを示したのが【ヤングの実験】です。単色光を、間隔 d の2つのスリット S₁・S₂ に当てると、距離 L はなれたスクリーンに明暗のしま(干渉じま)ができます。\nなぜしまができるのか:S₁ と S₂ からは同じ光(同じ位相)が出ます。スクリーン上の点Pまでの道のり(経路)が S₁P と S₂P でちがうので、Pに着いたときの位相がずれます。【経路差が波長の整数倍なら強め合い(明線)、半整数倍なら弱め合い(暗線)】です。\n経路差の求め方:Pのスクリーン中央 O からの距離を x とします。三平方の定理で S₂P²−S₁P²＝{L²＋(x＋d/2)²}−{L²＋(x−d/2)²}＝2dx。左辺を (S₂P−S₁P)(S₂P＋S₁P) と分解し、L が d や x よりずっと大きいので S₂P＋S₁P≒2L とすると、【経路差 S₂P−S₁P≒dx/L】 です。\nだから明線の条件は 【dx/L＝mλ】(m＝0, 1, 2, …)、暗線の条件は dx/L＝(m＋1/2)λ。明線の位置は x＝mLλ/d で、隣り合う明線の間隔は 【Δx＝Lλ/d】 です。\n間隔は波長に比例するので、赤い光(波長が長い)ほどしまの間隔は広く、青い光ほど狭くなります。白色光を使うと、中央は白く、その外側に色づいたしまができます。',
        key: '経路差≒dx/L。明線 dx/L＝mλ、しまの間隔 Δx＝Lλ/d。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="ヤングの実験。2つのスリットからスクリーン上の点Pまでの経路差が dx/L になる"><line x1="40" y1="15" x2="40" y2="58" class="ax"/><line x1="40" y1="66" x2="40" y2="84" class="ax"/><line x1="40" y1="92" x2="40" y2="122" class="ax"/><line x1="190" y1="15" x2="190" y2="122" class="ax"/><line x1="40" y1="62" x2="190" y2="35" class="cv"/><line x1="40" y1="88" x2="190" y2="35" class="cv2"/><line x1="40" y1="75" x2="190" y2="75" class="dash"/><circle cx="190" cy="35" r="3" class="pt"/><text x="18" y="64">S₁</text><text x="18" y="94">S₂</text><text x="44" y="79">d</text><text x="112" y="90">L</text><text x="176" y="30">P</text><text x="178" y="58">x</text><text x="178" y="90">O</text><text x="30" y="136">経路差 S₂P−S₁P≒dx/L</text><text x="30" y="148">明線:dx/L＝mλ</text></svg>',
        ex: [{ q: 'ヤングの実験で、スリット間隔 0.50 mm、スリットからスクリーンまで 1.0 m のとき、明線の間隔が 1.2 mm だった。光の波長を求めよ。', hint: 'Δx＝Lλ/d を λ について解きます。単位は m にそろえます。', steps: ['Δx＝Lλ/d より λ＝dΔx/L。', 'd＝0.50×10⁻³ m、Δx＝1.2×10⁻³ m、L＝1.0 m。', 'λ＝0.50×10⁻³×1.2×10⁻³/1.0＝6.0×10⁻⁷ m。'], a: '6.0×10⁻⁷ m(600 nm)', check: '可視光の波長はおよそ 3.8×10⁻⁷〜7.7×10⁻⁷ m なので、その範囲に入っていて妥当(だいだい色の光)。' }] },
      { h: '回折格子', t: 'ガラス板に、細いすじを等間隔にたくさん刻んだものを【回折格子】といいます。すじとすじの間が、たくさんのスリットの役をします。隣り合うスリットの間隔 d を【格子定数】といいます。\n導き方:格子に垂直に光を当て、角度 θ の方向に進む光を考えます。隣り合うスリットから出た光の経路差は 【d sinθ】 です(直角三角形の斜辺 d に対する、θ の向かいの辺)。\nこれが波長の整数倍なら、隣どうしが強め合い、それが全部のスリットで続くので、すべての光が強め合います。明線の条件は 【d sinθ＝mλ】(m＝0, 1, 2, …)。m を「次数」といいます。\nヤングの実験とのちがいは、スリットの数がとても多いことです。そのため、条件からわずかにずれた方向では光がほぼ打ち消し合い、明線が【鋭く明るく】なります。この性質を使って、光の波長を精密に測ることができます。\nsinθ は1をこえないので、見える明線の次数には上限があります(mλ＜d)。白色光を当てると、波長ごとに曲がる角度がちがうので、虹のように分かれます(CD の表面が虹色に見えるのも同じしくみです)。',
        key: '回折格子の明線:d sinθ＝mλ。sinθ＜1 から、見える次数に上限がある。',
        ex: [{ q: '1 mm あたり 500 本のすじが刻まれた回折格子に、波長 5.0×10⁻⁷ m の光を垂直に当てた。1次の明線の方向の sinθ を求めよ。また、明線は全部で何本見えるか。', hint: 'まず格子定数 d を m で求めます。', steps: ['d＝1.0×10⁻³ m÷500＝2.0×10⁻⁶ m。', '1次:sinθ＝λ/d＝5.0×10⁻⁷/2.0×10⁻⁶＝0.25。', '次数の上限:sinθ＝mλ/d＜1 より m＜d/λ＝4。m＝4 では sinθ＝1(θ＝90°)で、光はスクリーンに届かない。', '見えるのは m＝0, ±1, ±2, ±3 の 7 本。'], a: 'sinθ＝0.25、明線は 7 本', check: 'm＝3 なら sinθ＝0.75 で1より小さく見える。m＝4 では sinθ＝1 となり格子面に沿う向きなので、数えない。' }] },
      { h: '薄膜の干渉と光路差', t: 'シャボン玉や水面の油膜が色づいて見えるのは、【薄膜の干渉】です。膜の上の面で反射した光と、膜に入って下の面で反射した光が重なります。\n考えるべきことは2つあります。1つ目は【光路差】です。屈折率 n の物質の中では光の波長が λ/n に縮むので、物質中の長さ l は、真空中の長さ nl に相当します。この nl を【光学距離(光路長)】といいます。厚さ d の膜に垂直に光が入って往復すると、光路差は 【2nd】 です。\n2つ目は【反射による位相のずれ】です。屈折率の小さい物質から大きい物質への境界で反射するとき、光は固定端反射のように位相が π ずれます(半波長ずれたのと同じ)。大きい物質から小さい物質への反射では、ずれません。\n空気中のシャボン膜(屈折率 n＞1)では、上の面(空気→膜)の反射で π ずれ、下の面(膜→空気)ではずれません。片方だけずれるので、強め合いの条件が半波長分ずれて、【反射光が強め合う条件は 2nd＝(m＋1/2)λ】、弱め合う条件は 2nd＝mλ になります。\nガラスの上の油膜のように、両方の反射で π ずれる場合は、ずれが打ち消されて、強め合いは 2nd＝mλ です。斜めに入る光では、光路差が 2nd cos r(r は膜の中での屈折角)になります。\n同じ考え方で、2枚のガラス板の間にくさび形の空気層をつくった場合(くさび形の干渉)や、レンズとガラス板の間の空気層によるニュートンリングも説明できます。',
        key: '光路差は「屈折率×長さ」。屈折率の小→大の境界での反射は位相が π ずれる。ずれる回数で条件が半波長分変わる。',
        ex: [{ q: '空気中にある屈折率 1.5 の薄い膜に、波長 600 nm の光を垂直に当てた。反射光が強め合うような膜の厚さのうち、最も薄いものを求めよ。', hint: '上の面の反射だけ位相が π ずれるので、2nd＝(m＋1/2)λ を使います。', steps: ['上の面(空気→膜)の反射で位相が π ずれ、下の面(膜→空気)ではずれない。', '反射光が強め合う条件:2nd＝(m＋1/2)λ(m＝0, 1, 2, …)。', '最も薄いのは m＝0 のとき:2×1.5×d＝(1/2)×600 nm。', 'd＝300/3.0＝100 nm(1.0×10⁻⁷ m)。'], a: '100 nm(1.0×10⁻⁷ m)', check: '膜中の波長は 600/1.5＝400 nm。往復 200 nm は膜中の半波長で、反射の π のずれと合わせてちょうど1波長ずれ、強め合う。' }] },
      { h: '干渉の問題を解く共通の手順', t: 'ヤングの実験・回折格子・薄膜・くさびなど、干渉の問題はたくさんの種類がありますが、考え方は1つです。\n【手順1】重なり合う2つの光(波)が、どこから来てどこで出会うのかを図にかく。\n【手順2】2つの道のりの差(物質中なら光路差＝屈折率×長さの差)を求める。近似が必要なら、L が十分大きい、角度が小さい、などの条件を使う。\n【手順3】反射による位相のずれを数える。π のずれが0回か2回なら「そのまま」、1回なら「条件を半波長分ずらす」。\n【手順4】「光路差＝mλ(またはm＋1/2)λ」の式を立てて解く。\nこの手順を守ると、新しい装置の問題でも同じように解けます。暗記した式が使えない場面でも、図から経路差を作れることが大切です。',
        key: '干渉は「経路差(光路差)」と「反射による位相のずれの回数」の2つで決まる。' },
      { h: 'もっと深く:ドップラー効果を「波の数」で導き直す', t: 'ドップラー効果の式は、【1秒間に出る波の数は振動数 f で、その波が並ぶ長さ】を考えると、暗記せずに導けます。\n音源が速さ v で観測者に近づくとき、音源が1秒間に出した f 個の波は、音が1秒で進む V と、音源が進む v の差、つまり長さ V−v の中につめこまれます。だから波長は λ′＝(V−v)/f と短くなります。静止した観測者には、この波が速さ V でやってくるので、f′＝V/λ′＝Vf/(V−v) です。\n観測者が速さ u で音源に近づく場合は、空気中の波長は λ＝V/f のまま変わりません。観測者から見ると波が V＋u の速さで向かってくるので、1秒間に受け取る波の数は f′＝(V＋u)/λ＝(V＋u)f/V になります。これが、音源の速さは分母、観測者の速さは分子に入る理由です。\n【風が吹いているとき】は、音は空気に対して V で進むので、地面から見た音速が風の分だけ変わります。風下に向かう音では音速を V＋w、風上に向かう音では V−w として、同じ式を使います。\n【反射板があるとき】は2段階で考えます。①反射板を「観測者」として、反射板が受け取る振動数を求める。②次に反射板を、その振動数の音を出す「音源」と見なして、観測者が聞く振動数を求める。反射板が動いていれば、①と②の両方でドップラー効果が起こります。\n【斜めに動くとき】は、音源と観測者を結ぶ方向の速度の成分だけを使います。真横を通り過ぎる瞬間は、その方向の成分が0なので、その瞬間に出た音は元の振動数で聞こえます。',
        key: '音源の運動は波長を変え(分母)、観測者の運動は受け取るペースを変える(分子)。反射板は「観測者→音源」の2段階。斜めのときは結ぶ方向の成分だけ。' },
      { h: '入試ではこう出る:反射音のうなりと、干渉じまのずれ', t: '波の分野の入試では、ドップラー効果と光の干渉が2大テーマです。どちらも、基本の式を「1段ずつ」使う力が問われます。\n【型1:反射音とうなり】音源が壁に近づき、直接音と反射音の両方を聞く問題がよく出ます。直接音と反射音のそれぞれの振動数を求め、その差が1秒あたりの【うなりの回数】です。反射音は「壁が観測者→壁が音源」の2段階で求めます(壁が静止していれば、壁が出す振動数は壁が受け取った振動数のまま)。\n【型2:干渉装置全体を液体に入れる】ヤングの実験の装置全体を屈折率 n の液体に入れると、光の波長が λ/n になるので、明線の間隔 Δx＝Lλ/d も 1/n 倍になります。振動数は変わりません。\n【型3:片方のスリットを薄膜でおおう】厚さ t、屈折率 n の膜で一方のスリットをおおうと、その経路の光学距離が (n−1)t だけ長くなります。中央の明線(光学距離が等しい点)は、【おおったスリットの側にずれます】。(n−1)t が λ の何倍かで、明線が何本分ずれるかが分かります。\nひっかけとして多いのは、①うなりの回数を振動数の和で計算する、②液体中では波長だけでなく振動数も変わると考える、③薄膜による光学距離の増加を nt としてしまう(空気の分 t を引き忘れる)、の3つです。\n時間配分のコツ:ドップラー効果は「だれが音源で、だれが観測者か」を矢印で図に書くと、符号のミスがほぼなくなります。',
        key: 'うなりの回数＝2つの振動数の差。装置を液体に入れると明線間隔は 1/n 倍。膜でおおうと光学距離が (n−1)t 増え、明線はおおった側へずれる。',
        ex: [{ q: '振動数 576 Hz の音を出す音源が、静止した壁に向かって 20 m/s で近づいている。音源の後方で静止している観測者には、音源からの直接音と壁からの反射音が聞こえる。それぞれの振動数と、1秒あたりのうなりの回数を求めよ。(音速 340 m/s)', hint: '直接音は「遠ざかる音源」、反射音は「近づく音源の音を受けた壁」が出す音です。', steps: ['直接音:観測者から見て音源は遠ざかるので、f₁＝340/(340＋20)×576＝(340/360)×576＝544 Hz。', '壁が受け取る振動数:音源は壁に近づくので、f₂＝340/(340−20)×576＝(340/320)×576＝612 Hz。', '壁は静止しているので、612 Hz の音をそのまま反射し、観測者には 612 Hz で届く。', 'うなりの回数＝612−544＝68 回/s。'], a: '直接音 544 Hz、反射音 612 Hz、うなり 毎秒 68 回', check: '近づく側の音(612 Hz)は 576 Hz より高く、遠ざかる側の音(544 Hz)は低い。向きの判断と矛盾しない。' }, { q: 'ヤングの実験で、空気中では明線の間隔が 1.2 mm だった。(1)装置全体を屈折率 1.5 の液体中に入れると、明線の間隔はいくらになるか。(2)空気中に戻し、一方のスリットを厚さ 6.0×10⁻⁶ m、屈折率 1.5 の薄膜でおおった。光の波長が 6.0×10⁻⁷ m のとき、明線は何本分、どちらへずれるか。', hint: '(2)は、膜による光学距離の増加 (n−1)t が波長の何倍かを考えます。', steps: ['(1)液体中では波長が λ/1.5 になる。Δx＝Lλ/d は波長に比例するので 1.2/1.5＝0.80 mm。', '(2)膜をおおうと、その経路の光学距離は (n−1)t＝(1.5−1)×6.0×10⁻⁶＝3.0×10⁻⁶ m 長くなる。', '3.0×10⁻⁶/6.0×10⁻⁷＝5 なので、光学距離の差がちょうど5波長分変わる。', '光学距離が等しくなる点は、幾何学的な道のりがおおったスリットの側で短くなる位置、つまりおおった側へずれる。'], a: '(1) 0.80 mm (2) 明線5本分、膜でおおったスリットの側へずれる', check: '(2)で、ずれる距離は 5×1.2 mm＝6.0 mm。5 が整数なので、ずれた後の模様は元と同じに見える点にも注意。' }] }
    ],
    faq: [['ドップラー効果で、音源が動くときと観測者が動くときで式の形がちがうのはなぜ?', '音源が動くと、空気中にできる波そのものの波長が変わります(前方でつまる)。観測者が動いても、空気中の波長は変わらず、観測者が波を受け取るペースが変わるだけです。\nこのように原因がちがうので、音源の速さは分母、観測者の速さは分子に入ります。同じ速さでも、音源が近づく場合と観測者が近づく場合で、振動数の変化はわずかにちがいます。'],
      ['光が屈折率の大きい物質に入ると、色(振動数)は変わるの?', '変わりません。振動数は波を出す源で決まり、境界を通っても変わりません。変わるのは速さと波長で、どちらも 1/n 倍になります。\n水の中でも物の色が同じに見えるのは、振動数が変わらないからです。'],
      ['なぜ厚いガラス板では干渉の色が見えないの?', '太陽光などの光は、とぎれとぎれの短い波の集まりで、遠く離れた部分どうしは位相がそろっていません。厚い板では、表と裏で反射した光の光路差が大きすぎて、もとは別の波の部分が重なるので、干渉じまが見えなくなります。\nまた、光路差が大きいと、強め合う波長がたくさん並んで、色が混ざって白っぽく見えるという理由もあります。'],
      ['風が吹いていると、ドップラー効果の式はどう変わるの?', '音は空気(媒質)に対して決まった速さ V で伝わります。風が吹くと空気ごと動くので、地面から見た音速が変わります。\n音が風下へ進むなら音速を V＋w、風上へ進むなら V−w に置きかえ、あとは同じ式を使います。音源と観測者がどちらも静止していれば、風があっても振動数は変わりません(波長と音速が同じ割合で変わるからです)。']],
    drill: [
      { lv: 1, q: '振動数 400 Hz の音を出す音源が、静止した観測者から 20 m/s で遠ざかっている。観測者が聞く振動数を求めよ。(音速 340 m/s)', a: '約 3.8×10² Hz(約 378 Hz)', exp: '音源が遠ざかると、音源の後ろ側では波が引きのばされ、波長が長くなります。\nf′＝V/(V＋v)×f＝340/360×400≒378 Hz。\n遠ざかるので元の 400 Hz より低くなっていることを確かめましょう。' },
      { lv: 1, q: '格子定数 2.0×10⁻⁶ m の回折格子に単色光を垂直に当てたところ、2次の明線が sinθ＝0.60 の方向に見えた。光の波長を求めよ。', a: '6.0×10⁻⁷ m', exp: '回折格子で明線ができる条件は d sinθ＝mλ です。\nm＝2 なので λ＝d sinθ/2＝2.0×10⁻⁶×0.60/2＝6.0×10⁻⁷ m。\n次数 m で割り忘れると 1.2×10⁻⁶ m となり、可視光の範囲(約 4×10⁻⁷〜8×10⁻⁷ m)から外れるので気づけます。' },
      { lv: 2, q: '振動数 680 Hz の音を出す静止した音源に向かって、観測者が 17 m/s で近づいている。観測者が聞く振動数を求めよ。また、観測者が同じ速さで遠ざかるときの振動数も求めよ。(音速 340 m/s)', a: '近づくとき 714 Hz、遠ざかるとき 646 Hz', exp: '観測者が動いても空気中の波長は変わりません。観測者が近づくと、波を受け取るペースが速くなります。\n近づくとき:f′＝(V＋u)/V×f＝357/340×680＝357×2＝714 Hz。\n遠ざかるとき:f′＝(V−u)/V×f＝323×2＝646 Hz。\n変化の量はどちらも 34 Hz で等しくなります(観測者が動く場合は、振動数が速さに比例して変わるため)。' },
      { lv: 2, q: '長さ 0.10 m の2枚の平面ガラスを重ね、一端に薄い紙をはさんで、くさび形の空気層をつくった。真上から波長 6.0×10⁻⁷ m の光を当てて反射光を見ると、暗線が 1.5 mm 間隔で並んだ。紙の厚さを求めよ。', a: '2.0×10⁻⁵ m', exp: '接している端からの距離 x の位置の空気層の厚さは D x/L(D は紙の厚さ)です。光は空気層を往復するので、経路差は 2Dx/L。\n暗線は経路差が λ ずつ変わるごとに現れるので、隣り合う暗線の間隔 Δx は 2DΔx/L＝λ を満たします。よって Δx＝λL/(2D)。\nD＝λL/(2Δx)＝6.0×10⁻⁷×0.10/(2×1.5×10⁻³)＝2.0×10⁻⁵ m(0.020 mm)。\n反射による位相のずれは、どの位置でも同じ条件なので、間隔の計算には影響しません。' },
      { lv: 3, q: 'ガラス(屈折率 1.5)のレンズの表面に、屈折率 1.38 の薄い膜をつけて、波長 550 nm の光の反射を弱めたい(反射防止膜)。光が垂直に入射するとき、必要な膜の最小の厚さを求めよ。', a: '約 1.0×10² nm(約 100 nm)', exp: '膜の上面(空気→膜:屈折率が小→大)でも、下面(膜→ガラス:1.38→1.5、小→大)でも反射で位相が π ずれます。両方ずれるので、反射による差は打ち消し合います。\nしたがって、弱め合いの条件は光学距離の差だけで決まり、2nd＝(m＋1/2)λ(m＝0, 1, 2, …)。\n最小は m＝0 で d＝λ/(4n)＝550/(4×1.38)≒99.6 nm、約 1.0×10² nm です。\n「どちらの面で位相がずれるか」を先に数えるのが、薄膜の問題の型です。' },
      { lv: 3, q: '静止した音源(振動数 800 Hz)の位置に観測者がいる。反射板が音源に向かって 20 m/s で近づいてくる。観測者が聞く反射音の振動数と、直接音との間に生じる1秒あたりのうなりの回数を求めよ。(音速 340 m/s)', a: '反射音 900 Hz、うなり 毎秒 100 回', exp: '2段階で考えます。①反射板を観測者と見る:近づく観測者なので、反射板が受け取る振動数は f₁＝(340＋20)/340×800。\n②反射板を音源と見る:f₁ の音を出しながら観測者に近づく音源なので、f₂＝340/(340−20)×f₁。\nまとめると f₂＝(360/320)×800＝900 Hz。途中の 340 は約分で消えます。\n直接音は 800 Hz のままなので、うなりは 900−800＝100 回/s です。' }
    ],
    terms: [['波の式', 'y＝A sin 2π(t/T−x/λ)。正の向きに進む正弦波'], ['ドップラー効果', '音源や観測者の運動で、観測される振動数が変わる現象'], ['経路差', '2つの波が出会う点までの道のりの差'], ['光学距離', '屈折率×物質中の長さ。真空中に直した長さ'], ['干渉じま', '強め合い(明線)と弱め合い(暗線)がくり返すしま模様'], ['格子定数', '回折格子のすじの間隔 d'], ['固定端反射', '反射で位相が π ずれる反射。光では屈折率の小→大の境界']],
    miss: ['ドップラー効果の式で、速度の正の向きをまちがえる。→ 「音源→観測者が正」と図に矢印をかいてから、各速度の符号を決めます。', '薄膜の干渉で、反射による位相のずれを忘れる。→ 境界ごとに「屈折率 小→大 か?」を確かめ、ずれの回数を数えます。', '光路差を 2d(屈折率をかけない)で計算する。→ 物質中の道のりには必ず屈折率 n をかけます。', 'ヤングの実験のしま間隔を Ldλ や dλ/L と覚えまちがえる。→ 「スリット間隔が狭いほど、しまは広がる」ので d は分母、と意味で確かめます。'],
    sum: ['正の向きに進む波:y＝A sin 2π(t/T−x/λ)。位置 x の点は x/v 遅れる。', 'ドップラー効果 f′＝(V−v₀)/(V−vₛ)×f(音源→観測者の向きが正)。', 'ヤングの実験:経路差 dx/L、明線間隔 Δx＝Lλ/d。', '回折格子:d sinθ＝mλ。', '薄膜:光路差 2nd。屈折率の小→大の反射で位相が π ずれる。'],
    next: '次は『電気:電場・電位・コンデンサー・直流回路(物理)』へ。光の正体である電磁波は、電場と磁場の振動が伝わる波です。'
  };

  // ===== 電気 =====
  L.p4_elec = {
    goal: 'クーロンの法則・電場・電位の関係を理解し、コンデンサーの電気量とエネルギーを求め、キルヒホッフの法則で直流回路の電流を計算できるようになる。',
    intro: '冬にドアノブでパチッとくるのは、体にたまった電気が一気に流れるからです。電気の力は目に見えませんが、「高さ」と「水の流れ」にたとえると、ぐっと分かりやすくなります。電位は電気の世界の高さ、電流は水の流れ、電池はポンプです。この単元では、電荷どうしの力から始めて、電場・電位という考え方を作り、コンデンサーや回路の計算へとつなげます。',
    pre: '【電荷と電気量】物体がもつ電気を電荷、その量を電気量といい、単位は C(クーロン)です。電子1個の電気量は −1.6×10⁻¹⁹ C(この大きさ e を電気素量という)。同じ符号の電荷は反発し、ちがう符号は引き合います。\n【電流】1秒あたりに導線の断面を通る電気量です。I＝Q/t、単位は A。電流の向きは正の電荷が動く向きと決めているので、電子は電流と逆向きに動きます。\n【オームの法則】抵抗 R〔Ω〕に電流 I が流れると、電圧 V＝RI がかかります。直列では抵抗の和、並列では逆数の和の逆数が合成抵抗です。\n【電力】P＝VI＝RI²＝V²/R〔W〕。電力量(ジュール熱)は Pt〔J〕です。\n【仕事と位置エネルギー】重力に逆らって物体を持ち上げると、位置エネルギーがたくわえられます。電気の世界でも同じように、電気力に逆らって電荷を動かすと、電気的な位置エネルギーがたくわえられます。',
    secs: [
      { h: 'クーロンの法則', t: '2つの点電荷(大きさを無視できる電荷)の間にはたらく力を【静電気力(クーロン力)】といいます。\n電気量 q₁、q₂ の点電荷が距離 r 離れているとき、力の大きさは 【F＝kq₁q₂/r²】。k はクーロンの法則の比例定数で、真空中で約 9.0×10⁹ N·m²/C² です。これを【クーロンの法則】といいます。\n万有引力の式 F＝GMm/r² とよく似ていて、どちらも距離の2乗に反比例します。ちがいは、静電気力には引力と斥力(反発する力)の両方があることと、k が G よりはるかに大きいことです。\n力の向きは2つの電荷を結ぶ直線上で、同符号なら斥力、異符号なら引力です。3つ以上の電荷があるときは、1つずつの力を求めてベクトルとして足し合わせます。\n計算では、まず大きさを符号なしで求め、向きは図で決めると、ミスが減ります。',
        key: 'F＝kq₁q₂/r²(k≒9.0×10⁹ N·m²/C²)。距離の2乗に反比例し、同符号は斥力、異符号は引力。',
        ex: [{ q: '真空中で、＋2.0×10⁻⁶ C と ＋3.0×10⁻⁶ C の点電荷が 0.30 m 離れている。はたらく静電気力の大きさと、引力か斥力かを答えよ。(k＝9.0×10⁹ N·m²/C²)', hint: 'F＝kq₁q₂/r² に代入します。指数の計算に注意。', steps: ['q₁q₂＝2.0×10⁻⁶×3.0×10⁻⁶＝6.0×10⁻¹² C²。', 'r²＝0.30²＝0.090 m²。', 'F＝9.0×10⁹×6.0×10⁻¹²/0.090＝5.4×10⁻²/0.090＝0.60 N。', 'どちらも正の電荷なので斥力。'], a: '0.60 N、斥力', check: '9.0×6.0＝54、10⁹×10⁻¹²＝10⁻³ なので分子は 0.054。0.054÷0.09＝0.6 で一致する。' }] },
      { h: '電場と電気力線', t: '電荷のまわりの空間は、ほかの電荷に力をおよぼす性質をもっています。この性質を【電場(電界)】といいます。\n電場の強さは、その点に ＋1 C の電荷を置いたときに受ける力で表します。電荷 q が力 F を受けるなら 【E＝F/q】、つまり 【F＝qE】。単位は N/C です。電場は向きをもつベクトルで、正の電荷が受ける力の向きが電場の向きです。\n点電荷 Q がつくる電場は、クーロンの法則で q＝1 とおけば求まります。【E＝kQ/r²】。Q が正なら外向き、負なら内向きです。\n電場のようすを表す線を【電気力線】といいます。正の電荷から出て負の電荷に入り、線の接線の向きが電場の向き、線の密度(面積あたりの本数)が電場の強さを表します。電気力線は途中で交わったり、枝分かれしたりしません。\n電気力線の本数で考えると、点電荷 Q から出る電気力線は 4πkQ 本と決められます(ガウスの法則)。半径 r の球面(面積 4πr²)を通る密度は 4πkQ/(4πr²)＝kQ/r² となり、電場の強さと一致します。この考え方は、次のコンデンサーで使います。',
        key: 'F＝qE。点電荷の電場 E＝kQ/r²。電気力線の密度が電場の強さ。' },
      { h: '電位と電位差', t: '重力の世界で「高さ」があるように、電気の世界には【電位】があります。電位は、＋1 C の電荷がその点でもつ電気的な位置エネルギーです。単位は V(ボルト)で、1 V＝1 J/C です。\n電荷 q が電位 V の点にあると、位置エネルギーは 【U＝qV】。電位差 V の2点間を電荷 q が移動すると、静電気力は qV の仕事をします。電子を電位差 V で加速すると、運動エネルギー eV を得ます。\n一様な電場の電位差:強さ E の一様な電場の中で、電場の向きに距離 d だけ ＋1 C を動かすと、静電気力は E×d の仕事をします。この分だけ位置エネルギー(電位)が下がるので、【V＝Ed】 です。このことから、電場の単位は V/m とも書けます。\n点電荷 Q からの距離 r の点の電位は、無限遠を基準(0 V)として 【V＝kQ/r】 です(電場とちがい、1乗に反比例)。\n電位の等しい点を結んだ面を【等電位面】といい、電気力線と垂直に交わります。地図の等高線と、傾斜の向きの関係と同じです。電場は「電位が高い所から低い所へ」向かいます。',
        key: '電位は ＋1 C あたりの位置エネルギー(U＝qV)。一様な電場では V＝Ed。',
        ex: [{ q: '間隔 0.020 m の平行な2枚の金属板に、100 V の電位差をかけた。板の間の電場の強さと、電子(電気量 −1.6×10⁻¹⁹ C)が受ける力の大きさを求めよ。また、電子が負の板から正の板まで移動する間に、静電気力がする仕事はいくらか。', hint: '平行板の間は一様な電場とみなせます。V＝Ed を使います。', steps: ['E＝V/d＝100/0.020＝5.0×10³ V/m。', '力の大きさ F＝eE＝1.6×10⁻¹⁹×5.0×10³＝8.0×10⁻¹⁶ N。', '電子は電場と逆向き(正の板の向き)に力を受ける。', '仕事 W＝eV＝1.6×10⁻¹⁹×100＝1.6×10⁻¹⁷ J。'], a: '電場 5.0×10³ V/m、力 8.0×10⁻¹⁶ N、仕事 1.6×10⁻¹⁷ J', check: '仕事＝力×距離 でも 8.0×10⁻¹⁶×0.020＝1.6×10⁻¹⁷ J で一致する。' }] },
      { h: 'コンデンサー', t: '2枚の金属板を向かい合わせて、電気をたくわえる部品を【コンデンサー】といいます。電池につなぐと、片方の板に ＋Q、もう片方に −Q がたまります。\nたまる電気量は電圧に比例します。【Q＝CV】。比例定数 C を【電気容量】といい、単位は F(ファラド)です。ふつうは μF(10⁻⁶ F)程度の小さな値です。\n平行板コンデンサーの電気容量の導き方:電気量 Q から出る電気力線は 4πkQ 本で、それが面積 S の板の間をまっすぐ通るので、電場は E＝4πkQ/S。電位差は V＝Ed＝4πkQd/S。これを Q＝CV と比べると C＝S/(4πkd)。ε₀＝1/(4πk)(真空の誘電率)とおくと、【C＝ε₀S/d】 です。\n板の間に誘電体(紙やプラスチックなど)を入れると、電気容量は比誘電率 εᵣ 倍になります(C＝εᵣε₀S/d)。\n【接続】並列では電圧が共通で、電気量が足し算になるので C＝C₁＋C₂。直列では電気量が共通で、電圧が足し算になるので 1/C＝1/C₁＋1/C₂。抵抗の場合と逆になる点に注意します。\n【静電エネルギー】充電の途中、電圧 v のときに少しの電気量 Δq を運ぶ仕事は vΔq です。Q-V グラフでは細い長方形の面積なので、充電し終わるまでの合計は三角形の面積 【U＝(1/2)QV＝(1/2)CV²＝Q²/(2C)】 になります。電池がした仕事 QV のうち、半分がコンデンサーにたくわえられ、残りは導線のジュール熱などになります。',
        key: 'Q＝CV、C＝εS/d。並列は C₁＋C₂、直列は逆数の和。エネルギー U＝(1/2)CV²(Q-V グラフの面積)。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="コンデンサーのQ-Vグラフ。傾きが電気容量C、三角形の面積が静電エネルギー(1/2)QV"><polygon points="30,125 170,40 170,125" class="fl"/><line x1="30" y1="125" x2="205" y2="125" class="ax"/><line x1="30" y1="125" x2="30" y2="12" class="ax"/><line x1="30" y1="125" x2="170" y2="40" class="cv"/><line x1="30" y1="40" x2="170" y2="40" class="dash"/><line x1="170" y1="40" x2="170" y2="125" class="dash"/><circle cx="170" cy="40" r="3" class="pt"/><text x="36" y="20">q</text><text x="184" y="140">v</text><text x="14" y="44">Q</text><text x="166" y="140">V</text><text x="56" y="70">傾き＝C</text><text x="96" y="112">面積＝(1/2)QV</text></svg>',
        ex: [{ q: '電気容量 2.0 μF のコンデンサーを 12 V の電池で充電した。たくわえられた電気量と静電エネルギーを求めよ。次に、電池を外してから極板の間隔を2倍にした。電圧と静電エネルギーはいくらになるか。', hint: '電池を外すと、電気量 Q が一定になります。', steps: ['Q＝CV＝2.0×10⁻⁶×12＝2.4×10⁻⁵ C。', 'U＝(1/2)CV²＝0.5×2.0×10⁻⁶×144＝1.44×10⁻⁴ J(約 1.4×10⁻⁴ J)。', '間隔を2倍にすると C＝εS/d は 1/2 倍で 1.0 μF。電池を外したので Q は 2.4×10⁻⁵ C のまま。', 'V＝Q/C＝2.4×10⁻⁵/1.0×10⁻⁶＝24 V。U＝(1/2)QV＝0.5×2.4×10⁻⁵×24＝2.88×10⁻⁴ J(約 2.9×10⁻⁴ J)。'], a: 'はじめ:2.4×10⁻⁵ C、約 1.4×10⁻⁴ J。間隔2倍の後:24 V、約 2.9×10⁻⁴ J', check: 'エネルギーが増えたのは、引き合う極板を引き離すのに外から仕事をしたから。増えた分 1.44×10⁻⁴ J がその仕事に等しい。' }] },
      { h: '直流回路と電池の内部抵抗', t: '導線の抵抗は、長さ l に比例し、断面積 S に反比例します。【R＝ρl/S】。ρ は【抵抗率】で、物質と温度で決まる値です(金属は温度が上がると抵抗率が大きくなる)。\nなぜ長いほど抵抗が大きいのか:電子は進む途中で金属の陽イオンにぶつかりながら進むので、道が長いほど妨げられます。断面積が大きいと、通れる道が多いので流れやすくなります。\n実際の電池は、中にも抵抗があります。これを【内部抵抗 r】といいます。起電力 E の電池に電流 I が流れると、内部抵抗で rI だけ電圧が下がるので、外に出てくる電圧(端子電圧)は 【V＝E−rI】 です。電流を多く流すほど、端子電圧は下がります。\n回路の消費電力は P＝VI です。抵抗 R では P＝RI²＝V²/R となり、すべてジュール熱になります。\n電圧計は測りたい部分に並列に、電流計は直列につなぎます。理想的な電圧計は抵抗が無限大、電流計は抵抗0として扱います。',
        key: 'R＝ρl/S。電池の端子電圧 V＝E−rI(内部抵抗の分だけ下がる)。',
        ex: [{ q: '起電力 1.5 V、内部抵抗 0.50 Ω の電池に、2.5 Ω の抵抗をつないだ。流れる電流と端子電圧を求めよ。', hint: '内部抵抗と外の抵抗は直列につながっていると考えます。', steps: ['回路全体の抵抗:0.50＋2.5＝3.0 Ω。', '電流 I＝E/(R＋r)＝1.5/3.0＝0.50 A。', '端子電圧 V＝E−rI＝1.5−0.50×0.50＝1.25 V(約 1.3 V)。'], a: '電流 0.50 A、端子電圧 1.25 V', check: '外の抵抗にかかる電圧 RI＝2.5×0.50＝1.25 V と一致する。' }] },
      { h: 'キルヒホッフの法則', t: '電池が2つ以上ある回路や、合成抵抗では簡単にならない回路は、【キルヒホッフの法則】で式を立てて解きます。\n【第1法則】回路の交点(分かれ目)では、流れこむ電流の和＝流れ出る電流の和。電荷が交点でたまったり消えたりしない(電気量の保存)ことを表しています。\n【第2法則】回路の中の1つの閉じた道すじ(閉回路)を1周すると、【起電力の和＝電圧降下(RI)の和】。1周するともとの点にもどるので、電位の上がり下がりの合計が0になる、ということです。山道を1周すると高さの変化の合計が0になるのと同じです。\n解き方:①各部分の電流に名前(I₁, I₂, …)と向きを仮に決める ②交点で第1法則 ③閉回路をいくつか選び、回る向きを決めて第2法則 ④連立方程式を解く。\n第2法則で符号をつけるとき、回る向きと電流の向きが同じ抵抗では RI を足し、逆なら引きます。電池は、回る向きに −極から ＋極へ通るなら起電力を ＋ にします。\n答えがマイナスになったら、仮に決めた向きと逆に流れていたということです。向きを最初に正しく当てる必要はありません。',
        key: '第1法則:交点で電流の出入りが等しい。第2法則:閉回路1周で起電力の和＝RI の和。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="2つの電池をふくむ回路。左に起電力7Vと1Ω、中央に2Ω、右に起電力2Vと2Ωが並列につながる"><line x1="30" y1="30" x2="170" y2="30" class="ax"/><line x1="30" y1="120" x2="170" y2="120" class="ax"/><line x1="30" y1="30" x2="30" y2="58" class="ax"/><line x1="20" y1="58" x2="40" y2="58" class="cv"/><line x1="25" y1="64" x2="35" y2="64" class="cv"/><line x1="30" y1="64" x2="30" y2="82" class="ax"/><rect x="24" y="82" width="12" height="24" class="bx"/><line x1="30" y1="106" x2="30" y2="120" class="ax"/><line x1="100" y1="30" x2="100" y2="62" class="ax"/><rect x="94" y="62" width="12" height="26" class="bx"/><line x1="100" y1="88" x2="100" y2="120" class="ax"/><line x1="170" y1="30" x2="170" y2="58" class="ax"/><line x1="160" y1="58" x2="180" y2="58" class="cv"/><line x1="165" y1="64" x2="175" y2="64" class="cv"/><line x1="170" y1="64" x2="170" y2="82" class="ax"/><rect x="164" y="82" width="12" height="24" class="bx"/><line x1="170" y1="106" x2="170" y2="120" class="ax"/><circle cx="100" cy="30" r="2.5" class="pt"/><circle cx="100" cy="120" r="2.5" class="pt"/><text x="42" y="64">7V</text><text x="42" y="98">1Ω</text><text x="110" y="80">2Ω</text><text x="140" y="64">2V</text><text x="140" y="98">2Ω</text><text x="4" y="98">I₁↑</text><text x="66" y="80">I₃↓</text><text x="146" y="22">I₂↑</text><text x="30" y="142">交点:I₁＋I₂＝I₃</text></svg>',
        ex: [{ q: '上の図の回路で、左の電池は起電力 7 V(上が＋極)、左の抵抗 1 Ω、中央の抵抗 2 Ω、右の電池は起電力 2 V(上が＋極)、右の抵抗 2 Ω である。電池の内部抵抗は無視する。左・右の枝を上向きに流れる電流 I₁・I₂ と、中央を下向きに流れる電流 I₃ を求めよ。', hint: '交点で1本、左の閉回路と右の閉回路で1本ずつ、合計3本の式を立てます。', steps: ['第1法則(上の交点):I₁＋I₂＝I₃。', '左の閉回路(左の枝を上へ→中央を下へ):7＝1×I₁＋2×I₃。', '右の閉回路(右の枝を上へ→中央を下へ):2＝2×I₂＋2×I₃。', '2式目から I₁＝7−2I₃、3式目から I₂＝1−I₃。これを1式目に入れて (7−2I₃)＋(1−I₃)＝I₃ → 8＝4I₃ → I₃＝2 A。', 'I₁＝7−4＝3 A、I₂＝1−2＝−1 A(マイナスなので、実際は右の枝を下向きに 1 A 流れる)。'], a: 'I₁＝3 A、I₂＝−1 A(右の枝を下向きに 1 A)、I₃＝2 A', check: '中央の抵抗の電圧は 2×2＝4 V。左の枝:7−1×3＝4 V、右の枝:2−2×(−1)＝4 V。3つの枝の上下の電位差がすべて 4 V で一致する。' }] },
      { h: 'もっと深く:導体と誘電体の中で電場はどうなるか', t: '【導体】(金属)の中には、自由に動ける電子(自由電子)がたくさんあります。導体を電場の中に置くと、自由電子が電場と逆向きに動いて表面にかたより、反対側の表面には正の電荷が残ります。これが【静電誘導】です。\n電子の移動は、表面の電荷がつくる電場が外の電場をちょうど打ち消すまで続きます。その結果、【導体の内部では電場が0、導体全体が等電位】になります。電気力線は導体の表面に垂直に出入りします。\n内部の電場が0になるので、中空の導体で囲まれた空間には外の電場が入りこみません。これを【静電遮蔽】といいます。精密な電子機器を金属のケースで囲むのはこのためです。\nコンデンサーの極板の間に、すき間の一部をうめるように厚さ t の金属板を入れると、金属板の中は電場が0なので、電位差が生じるのは残りの部分だけです。電気容量は【極板間隔が d−t になったコンデンサーと同じ】になり、容量は増えます。\n【誘電体】(紙・ガラス・プラスチックなど)には自由電子がありませんが、電場の中では分子の中の電荷がわずかにずれて、表面に電荷が現れます(【誘電分極】)。この電荷が外の電場を一部だけ打ち消すので、誘電体の中の電場は 1/εᵣ 倍に弱まります。同じ電気量 Q でも電位差が 1/εᵣ になるので、C＝Q/V は εᵣ 倍になるのです。\n発展:極板どうしが引き合う力は F＝QE ではなく (1/2)QE です。一方の極板が受ける電場は、もう一方の極板だけがつくる電場(全体の E の半分)だからです。',
        key: '導体内部は電場0・全体が等電位(静電遮蔽)。金属板を入れると間隔が減ったのと同じ。誘電体は分極で電場を 1/εᵣ に弱め、容量を εᵣ 倍にする。' },
      { h: '入試ではこう出る:コンデンサーのつなぎかえと、コンデンサーをふくむ回路', t: '電気の入試では、コンデンサーが最頻出です。公式 Q＝CV・C＝εS/d・U＝(1/2)CV² を知っているだけでは解けず、【何が一定に保たれるか】を見抜く力が問われます。\n【型1:つなぎかえ】充電したコンデンサーを電池から外し、別のコンデンサーとつなぐ問題です。ここで使うのは【電気量の保存】:導線でつながり、外とは絶縁された部分(孤立部分)の電気量の和は、つなぎかえの前後で変わりません。つないだ後は、つながった極板どうしが同じ電位になります。\n【型2:エネルギーの損失】つなぎかえの前後で静電エネルギーを比べると、ふつうは減っています。減った分は、電荷が移動するときに導線で生じたジュール熱(や電磁波)になったと考えます。「エネルギーが保存しない」ことに驚く必要はありません。\n【型3:コンデンサーをふくむ直流回路】スイッチを入れて十分に時間がたつと、コンデンサーには電流が流れなくなります。そこで、【コンデンサーの部分を切れた導線とみなして】回路の電流を求め、コンデンサーと並列な部分の電圧から Q＝CV を出します。スイッチを入れた直後は、逆にコンデンサーを「電圧0の導線」とみなします。\nひっかけとして多いのは、①電池を外したのに電圧一定と考える、②つなぎかえで異符号の極板どうしをつなぐ場合に電気量を単純に足す(引き算になる)、③十分時間がたった後もコンデンサーに電流が流れると考える、の3つです。\n時間配分のコツ:図に各極板の電気量を ＋Q、−Q と書きこみ、孤立部分を点線で囲んでから式を立てると、迷わず速く解けます。',
        key: 'つなぎかえは孤立部分の電気量保存。減った静電エネルギーはジュール熱。十分時間がたつとコンデンサーに電流は流れない。',
        ex: [{ q: '電気容量 2.0 μF のコンデンサーAを 12 V で充電してから電池を外し、充電されていない電気容量 4.0 μF のコンデンサーBと、同じ符号の極板どうしをつないだ。十分時間がたった後の電圧と、つなぐ前後で失われた静電エネルギーを求めよ。', hint: '電池を外しているので、電気量の和が保存されます。', steps: ['はじめのAの電気量:Q＝CV＝2.0×10⁻⁶×12＝24×10⁻⁶ C(24 μC)。', 'つないだ後、AとBの電圧は等しく V′。電気量保存:2.0V′＋4.0V′＝24(μC 単位)より V′＝4.0 V。', 'つなぐ前のエネルギー:(1/2)×2.0×10⁻⁶×12²＝1.44×10⁻⁴ J。', 'つないだ後:(1/2)×(2.0＋4.0)×10⁻⁶×4.0²＝4.8×10⁻⁵ J。差は 9.6×10⁻⁵ J。'], a: '電圧 4.0 V、失われたエネルギー 9.6×10⁻⁵ J(96 μJ)', check: 'Aに 8.0 μC、Bに 16 μC で、和 24 μC が保存されている。失われた 96 μJ は導線のジュール熱になる。' }, { q: '起電力 12 V(内部抵抗は無視)の電池に、2.0 Ω の抵抗 R₁ と 4.0 Ω の抵抗 R₂ を直列につなぎ、R₂ と並列に電気容量 3.0 μF のコンデンサーをつないだ。スイッチを入れて十分時間がたった後の、回路の電流とコンデンサーの電気量を求めよ。', hint: '十分時間がたつと、コンデンサーには電流が流れません。', steps: ['コンデンサーの枝には電流が流れないので、電流は R₁ と R₂ だけを通る:I＝12/(2.0＋4.0)＝2.0 A。', 'コンデンサーの電圧は R₂ の電圧に等しい:V＝4.0×2.0＝8.0 V。', 'Q＝CV＝3.0×10⁻⁶×8.0＝2.4×10⁻⁵ C。'], a: '電流 2.0 A、電気量 2.4×10⁻⁵ C(24 μC)', check: 'R₁ の電圧 4.0 V と R₂ の電圧 8.0 V の和が起電力 12 V に等しい。' }] }
    ],
    faq: [['電場と電位は、どうちがうの?', '電場は「力」の側の量で、向きをもつベクトルです(＋1 C が受ける力)。電位は「エネルギー」の側の量で、向きをもたないスカラーです(＋1 C がもつ位置エネルギー)。\n地形にたとえると、電位は高さ、電場は坂の傾きの急さと下る向きです。だから一様な電場では V＝Ed(高さの差＝傾き×距離)になります。'],
      ['コンデンサーの問題で、電池につないだままか外したかが大事なのはなぜ?', '電池につないだままなら、電圧 V が電池の起電力に保たれます。電池を外すと、電荷の逃げ場がないので、電気量 Q が一定に保たれます。\nどちらが一定かによって、極板の間隔を変えたときに Q や V、エネルギーの変わり方が逆になります。問題を読んだら最初に「V一定か Q一定か」を書きましょう。'],
      ['キルヒホッフの法則で、電流の向きをまちがえて仮定したらどうなるの?', '計算の結果がマイナスになるだけで、大きさは正しく求まります。マイナスは「仮定と逆向きに流れている」という意味です。\nただし、一度決めた向きは、すべての式で同じように使わなければいけません。式ごとに向きを変えると、正しい答えになりません。'],
      ['電位が 0 の点では、電場も 0 なの?', '関係ありません。電位は「高さ」、電場は「坂の傾き」なので、高さが 0 でも坂は急なことがあります。\nたとえば ＋Q と −Q の真ん中では電位は 0 ですが、電場は ＋ から − の向きに強くはたらいています。逆に ＋Q と ＋Q の真ん中では電場は 0 ですが、電位は 0 ではありません。']],
    drill: [
      { lv: 1, q: '真空中で、＋4.0×10⁻⁹ C の点電荷から 0.30 m 離れた点の電場の強さと電位を求めよ。(k＝9.0×10⁹ N·m²/C²、電位は無限遠を 0 とする)', a: '電場 4.0×10² N/C、電位 1.2×10² V', exp: '電場の強さは E＝kQ/r²＝9.0×10⁹×4.0×10⁻⁹/0.30²＝36/0.090＝400 N/C。向きは電荷から遠ざかる向きです。\n電位は V＝kQ/r＝36/0.30＝120 V。\n電場は r² で、電位は r で割る、というちがいに注意します。比べると E＝V/r の関係になっていて検算に使えます。' },
      { lv: 1, q: '電気容量 2.0 μF と 3.0 μF のコンデンサーがある。直列につないだときと、並列につないだときの合成容量を求めよ。', a: '直列 1.2 μF、並列 5.0 μF', exp: '並列では電圧が共通で電気量が足されるので、C＝C₁＋C₂＝5.0 μF。\n直列では電気量が共通で電圧が足されるので、1/C＝1/C₁＋1/C₂＝1/2.0＋1/3.0＝5/6、C＝1.2 μF。\n抵抗とは公式が逆になります。直列の合成容量は、どちらの容量よりも小さくなることも確かめましょう。' },
      { lv: 2, q: '強さ 200 V/m の一様な電場の中に、電場の向きに沿って 0.050 m 離れた2点A・Bがある(Aが上流側)。AB間の電位差を求めよ。また、＋2.0×10⁻⁶ C の電荷を、外力を加えてBからAまでゆっくり運ぶのに必要な仕事を求めよ。', a: '電位差 10 V(Aが高い)、仕事 2.0×10⁻⁵ J', exp: '一様な電場では V＝Ed＝200×0.050＝10 V。電場は電位の高い方から低い方へ向くので、上流側のAが高電位です。\n正の電荷を電位の低いBから高いAへ運ぶには、電場から受ける力に逆らう必要があります。\n外力の仕事 W＝qV＝2.0×10⁻⁶×10＝2.0×10⁻⁵ J。この仕事は電荷の静電気力による位置エネルギーとしてたくわえられます。' },
      { lv: 2, q: '電気容量 1.0 μF の平行板コンデンサーを 10 V で充電してから電池を外した。次に、極板の間を比誘電率 4.0 の誘電体ですき間なく満たした。電気容量・電圧・静電エネルギーは、それぞれいくらになるか。', a: '電気容量 4.0 μF、電圧 2.5 V、静電エネルギー 1.25×10⁻⁵ J(はじめの 1/4)', exp: '電池を外しているので、電気量 Q＝1.0×10⁻⁶×10＝1.0×10⁻⁵ C は変わりません。\n誘電体で満たすと容量は εᵣ 倍の 4.0 μF。電圧は V＝Q/C＝1.0×10⁻⁵/4.0×10⁻⁶＝2.5 V。\nエネルギーは Q²/(2C) で計算すると、はじめ 5.0×10⁻⁵ J、後 1.25×10⁻⁵ J で 1/4 倍。Q が一定のときは U＝Q²/(2C) を使うと見通しがよくなります。\n減ったエネルギーは、誘電体が極板の間に引きこまれるときの仕事などになります。' },
      { lv: 3, q: '抵抗 R₁＝10 Ω と R₂＝20 Ω を直列にした列と、抵抗 R₃＝15 Ω と未知の抵抗 Rx を直列にした列を、電池に並列につないだ(R₁ と R₃ が電池の同じ側)。R₁ と R₂ の接続点と、R₃ と Rx の接続点の間に検流計をつないだら、電流が流れなかった。Rx を求めよ。', a: '30 Ω', exp: '検流計に電流が流れないのは、2つの接続点の電位が等しいときです(ホイートストンブリッジのつり合い)。\nこのとき、R₁ と R₃ の電圧が等しく、R₂ と Rx の電圧も等しくなります。各列の電流を I₁、I₂ とすると、R₁I₁＝R₃I₂、R₂I₁＝RxI₂。\n2式を割り算すると R₁/R₂＝R₃/Rx。よって Rx＝R₂R₃/R₁＝20×15/10＝30 Ω。\n電池の起電力が分からなくても求められるのが、この方法の利点です。' },
      { lv: 3, q: '起電力 6.0 V、内部抵抗 1.0 Ω の電池に可変抵抗 R をつなぐ。R で消費される電力が最大になる R の値と、そのときの電力を求めよ。', a: 'R＝1.0 Ω のとき、最大 9.0 W', exp: '電流は I＝E/(R＋r)、R での消費電力は P＝RI²＝E²R/(R＋r)² です。\nP＝E²/{(R＋r)²/R}＝E²/{R＋2r＋r²/R} と変形すると、分母の R＋r²/R が最小のとき P が最大です。相加平均と相乗平均の関係から R＋r²/R≧2r で、等号は R＝r のとき。\nR＝r＝1.0 Ω のとき P＝E²/(4r)＝36/4＝9.0 W。\n検算:R＝2.0 Ω なら I＝2.0 A、P＝8.0 W、R＝0.50 Ω なら I＝4.0 A、P＝8.0 W で、どちらも 9.0 W より小さくなります。' }
    ],
    terms: [['クーロンの法則', 'F＝kq₁q₂/r²。点電荷どうしの静電気力'], ['電場', '＋1 C が受ける力。E＝F/q(N/C＝V/m)'], ['電位', '＋1 C がもつ位置エネルギー(V)'], ['等電位面', '電位の等しい点を結んだ面。電気力線と垂直'], ['電気容量', 'Q＝CV の比例定数 C(F)'], ['誘電率', 'C＝εS/d の ε。真空では ε₀＝1/(4πk)'], ['内部抵抗', '電池の中の抵抗。端子電圧は E−rI'], ['キルヒホッフの法則', '交点の電流の保存と、閉回路の電位の収支の2法則']],
    miss: ['点電荷の電位を kQ/r² と書く。→ 電場が r² に反比例、電位は r に反比例。「電位はエネルギーなので1乗」と区別します。', 'コンデンサーの直列・並列の合成を、抵抗と同じ式で計算する。→ コンデンサーは並列が足し算、直列が逆数の和で、抵抗と逆です。', '電池を外した後なのに、電圧が一定だとして計算する。→ 電池がなければ電荷は動けないので、Q が一定です。', 'キルヒホッフの第2法則で、電流と逆向きに回ったのに RI を足してしまう。→ 抵抗ごとに「回る向きと電流の向きが同じか」を確かめて符号を決めます。'],
    sum: ['クーロン力 F＝kq₁q₂/r²、点電荷の電場 E＝kQ/r²、電位 V＝kQ/r。', 'F＝qE、U＝qV。一様な電場では V＝Ed。', 'コンデンサー Q＝CV、C＝εS/d。エネルギー (1/2)CV²。', '並列 C₁＋C₂、直列 1/C＝1/C₁＋1/C₂。', '電池の端子電圧 V＝E−rI。キルヒホッフの2法則で回路の式を立てる。'],
    next: '次は『電磁気:磁場・ローレンツ力・電磁誘導・交流(物理)』へ。電流は磁場をつくり、磁場の変化は電流を生みます。'
  };

  // ===== 電磁気 =====
  L.p4_mag = {
    goal: '電流がつくる磁場と、電流・荷電粒子が磁場から受ける力を計算でき、電磁誘導・自己誘導・交流のしくみを、磁束の変化とエネルギーの考え方から説明できるようになる。',
    intro: '発電所の発電機も、スマートフォンのワイヤレス充電も、IH 調理器も、すべて「磁場が変化すると電流が生まれる」という1つの現象を使っています。逆に、電流を流すと磁場ができ、モーターが回ります。電気と磁気は、ばらばらのものではなく、たがいに生み出し合う関係にあるのです。この単元では、その関係を式と向きの法則で整理します。',
    pre: '【磁場と磁力線】磁石のまわりには磁場があり、方位磁針のN極が指す向きが磁場の向きです。磁力線はN極から出てS極に入ります。\n【右ねじの法則】電流の向きに右ねじが進むとき、ねじを回す向きに磁場ができます(中学の「電流のまわりの磁界」)。\n【フレミングの左手の法則】左手の中指を電流、人差し指を磁場の向きに合わせると、親指が力の向きになります(中指・人差し指・親指の順に「電・磁・力」)。\n【等速円運動】中心向きの力 F がはたらくと、m v²/r＝F の円運動をします(『力学の発展』で学習)。磁場中の荷電粒子の運動で使います。\n【電位と電場・コンデンサー】前の単元で学んだ V＝Ed、Q＝CV、(1/2)CV² は、この単元のコイルの式と形がよく似ています。並べて覚えると整理しやすくなります。',
    secs: [
      { h: '電流がつくる磁場', t: '磁場の強さは H〔A/m〕で表し、磁場の中の物質の性質を考えに入れた量を【磁束密度 B】〔T(テスラ)〕といいます。【B＝μH】 で、μ は【透磁率】、真空中では μ₀＝4π×10⁻⁷ N/A² です。\n【十分に長い直線電流】電流 I から距離 r の点の磁場は 【H＝I/(2πr)】。磁力線は電流を中心とする同心円で、向きは右ねじの法則で決まります。半径 r の円周の長さ 2πr に、電流 I が「均等に配られる」イメージです。\n【円形電流】半径 r の円形の導線の中心では 【H＝I/(2r)】。N 回巻きなら N 倍です。\n【ソレノイド】導線をつつ状に密に巻いたコイル(ソレノイド)の内部には、一様な磁場ができます。1 m あたりの巻き数を n とすると 【H＝nI】 です。内部に鉄心を入れると透磁率が大きくなり、B が大きくなります(電磁石)。\n電流が2本以上あるときは、それぞれがつくる磁場をベクトルとして足し合わせます。',
        key: '直線 H＝I/(2πr)、円形の中心 H＝I/(2r)、ソレノイド H＝nI。B＝μH。向きは右ねじの法則。',
        ex: [{ q: '真空中で、十分に長い直線の導線に 10 A の電流が流れている。導線から 0.20 m 離れた点の磁場の強さ H と、磁束密度 B を求めよ。(μ₀＝4π×10⁻⁷ N/A²、π＝3.14)', hint: 'まず H＝I/(2πr)、次に B＝μ₀H。', steps: ['H＝I/(2πr)＝10/(2×3.14×0.20)＝10/1.256≒8.0 A/m。', 'B＝μ₀H＝4π×10⁻⁷×10/(2π×0.20)。', 'π が約分できて B＝2×10⁻⁷×10/0.20＝1.0×10⁻⁵ T。'], a: 'H 約 8.0 A/m、B＝1.0×10⁻⁵ T', check: 'B＝μ₀I/(2πr)＝2.0×10⁻⁷×I/r と覚えておくと、2.0×10⁻⁷×10/0.20＝1.0×10⁻⁵ T ですぐ確かめられる。地磁気(約 5×10⁻⁵ T)より小さい程度で妥当。' }] },
      { h: '電流が磁場から受ける力', t: '磁場の中で電流を流すと、導線は力を受けます。これがモーターの原理です。\n磁束密度 B の磁場に垂直に、長さ L の導線を置いて電流 I を流すと、力の大きさは 【F＝IBL】。向きはフレミングの左手の法則で決まり、電流と磁場の両方に垂直です。導線が磁場と角度 θ をなすときは F＝IBL sinθ で、平行なら力は0です。\nこの式は磁束密度の定義にもなっています。1 A の電流が流れる 1 m の導線が 1 N の力を受けるような磁場を、1 T とするのです。\n【平行な2本の電流】同じ向きの電流どうしは引き合い、逆向きどうしは反発します。一方の電流がつくる磁場 B＝μ₀I₁/(2πr) から、もう一方が受ける力は 1 m あたり F＝μ₀I₁I₂/(2πr) です。\n静電気力とは逆で、「同じ向きは引き合う」ことに注意しましょう。',
        key: 'F＝IBL(垂直のとき)。向きはフレミングの左手の法則。同じ向きの平行電流は引き合う。' },
      { h: 'ローレンツ力と荷電粒子の運動', t: '電流が磁場から力を受けるのは、導線の中を動く電子一つひとつが力を受けているからです。動く荷電粒子が磁場から受ける力を【ローレンツ力】といいます。\n導き方:断面積 S の導線に、電気量 q の粒子が 1 m³ あたり n 個あり、速さ v で動いているとします。電流は I＝qnvS です。長さ L の部分には nSL 個の粒子があるので、1個あたりの力は IBL/(nSL)＝qnvS×BL/(nSL)＝【qvB】 となります。\nローレンツ力は【いつも速度に垂直】にはたらくので、仕事をしません。だから速さは変わらず、向きだけが変わります。\n一様な磁場に垂直に入った粒子は、ローレンツ力を向心力として等速円運動をします。m v²/r＝qvB より 【r＝mv/(qB)】、周期は 【T＝2πr/v＝2πm/(qB)】。周期は速さによらないので、加速器(サイクロトロン)に利用されています。\n力の向きは、正の電荷なら電流と同じに考えて左手の法則を使い、負の電荷(電子)なら逆向きにします。',
        key: 'ローレンツ力 f＝qvB は速度に垂直で仕事をしない。磁場中で等速円運動 r＝mv/(qB)、T＝2πm/(qB)。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="紙面の表から裏へ向かう磁場の中で、正の電荷がローレンツ力を向心力として等速円運動する"><circle cx="75" cy="80" r="45" class="ax"/><circle cx="75" cy="80" r="2.5" class="pt"/><line x1="75" y1="80" x2="120" y2="80" class="dash"/><circle cx="75" cy="35" r="5" class="tr"/><line x1="70" y1="35" x2="35" y2="35" class="cv"/><polyline points="42,31 35,35 42,39" class="cv"/><line x1="75" y1="41" x2="75" y2="62" class="cv2"/><polyline points="71,55 75,62 79,55" class="cv2"/><text x="14" y="62">×</text><text x="14" y="110">×</text><text x="50" y="132">×</text><text x="100" y="132">×</text><text x="128" y="110">×</text><text x="128" y="50">×</text><text x="52" y="100">×</text><text x="100" y="20">×</text><text x="40" y="28">v</text><text x="80" y="58">f</text><text x="94" y="94">r</text><text x="146" y="40">×:B は</text><text x="146" y="56">紙面の裏向き</text><text x="146" y="84">f＝qvB</text><text x="146" y="104">r＝mv/qB</text></svg>',
        ex: [{ q: '質量 2.0×10⁻²⁶ kg、電気量 1.6×10⁻¹⁹ C のイオンが、速さ 4.0×10⁵ m/s で、磁束密度 0.50 T の一様な磁場に垂直に入った。円運動の半径を求めよ。', hint: 'ローレンツ力が向心力になります。m v²/r＝qvB。', steps: ['m v²/r＝qvB より r＝mv/(qB)。', 'mv＝2.0×10⁻²⁶×4.0×10⁵＝8.0×10⁻²¹ kg·m/s。', 'qB＝1.6×10⁻¹⁹×0.50＝8.0×10⁻²⁰ C·T。', 'r＝8.0×10⁻²¹/8.0×10⁻²⁰＝0.10 m。'], a: '0.10 m', check: '速さを2倍にすると半径も2倍になる式の形(r は v に比例)。重いイオンほど曲がりにくいのも感覚と合う。' }] },
      { h: '電磁誘導', t: 'コイルに磁石を近づけたり遠ざけたりすると、電池がないのに電流が流れます。これを【電磁誘導】、生じる電圧を【誘導起電力】、流れる電流を【誘導電流】といいます。\n大切なのは【磁束】です。磁束密度 B の磁場に垂直な面積 S の面を貫く磁束は 【Φ＝BS】〔Wb(ウェーバ)〕。磁力線の「本数」のような量です。\n【ファラデーの電磁誘導の法則】N 回巻きのコイルに生じる誘導起電力は、コイルを貫く磁束の時間変化に比例します。【V＝−N ΔΦ/Δt】。磁束そのものの大きさではなく、【変化の速さ】で決まります。\n【レンツの法則】マイナスの符号は向きを表し、誘導電流は【磁束の変化を妨げる向き】に流れます。磁石のN極を近づける(下向きの磁束が増える)と、上向きの磁場をつくる向きに電流が流れます。もし変化を強める向きに流れたら、勝手に電流が増え続けてエネルギー保存に反してしまいます。\n【磁場中を動く導体棒】磁束密度 B の磁場に垂直なレールの上を、長さ L の棒が速さ v で動くと、Δt の間に回路の面積は LvΔt 増え、磁束は ΔΦ＝BLvΔt 増えます。よって 【V＝vBL】。棒の中の電子が受けるローレンツ力 evB から考えても、同じ式が出ます。\n誘導電流が流れると、棒は磁場から運動を妨げる向きの力 IBL を受けます。棒を一定の速さで動かし続けるには、外から仕事をしなければなりません。その仕事が、回路のジュール熱になります。',
        key: 'V＝−N ΔΦ/Δt(磁束の変化の速さで決まる)。向きは変化を妨げる向き(レンツの法則)。導体棒では V＝vBL。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="磁場中のレールの上を導体棒が速さvで動くと、誘導起電力vBLが生じる"><line x1="30" y1="40" x2="205" y2="40" class="ax"/><line x1="30" y1="110" x2="205" y2="110" class="ax"/><line x1="30" y1="40" x2="30" y2="62" class="ax"/><rect x="24" y="62" width="12" height="26" class="bx"/><line x1="30" y1="88" x2="30" y2="110" class="ax"/><line x1="130" y1="32" x2="130" y2="118" class="cv2"/><line x1="134" y1="75" x2="168" y2="75" class="cv"/><polyline points="161,71 168,75 161,79" class="cv"/><text x="60" y="64">×</text><text x="95" y="64">×</text><text x="60" y="96">×</text><text x="95" y="96">×</text><text x="180" y="96">×</text><text x="40" y="80">R</text><text x="148" y="68">v</text><text x="136" y="104">L</text><text x="20" y="134">V＝vBL(×:B は裏向き)</text><text x="20" y="148">面積が毎秒 Lv ずつ増える</text></svg>',
        ex: [{ q: '磁束密度 0.50 T の一様な磁場に垂直な水平レール(間隔 0.40 m)の上を、導体棒が 2.0 m/s で動いている。レールの端には 0.20 Ω の抵抗がつながっている(ほかの抵抗は無視)。誘導起電力、電流、棒が磁場から受ける力、棒を一定の速さで動かすための仕事率を求めよ。', hint: 'V＝vBL → I＝V/R → F＝IBL の順に求めます。', steps: ['誘導起電力 V＝vBL＝2.0×0.50×0.40＝0.40 V。', '電流 I＝V/R＝0.40/0.20＝2.0 A。', '棒が受ける力 F＝IBL＝2.0×0.50×0.40＝0.40 N(運動を妨げる向き)。', '一定の速さを保つには、外から 0.40 N の力で引く。仕事率 P＝Fv＝0.40×2.0＝0.80 W。'], a: '0.40 V、2.0 A、0.40 N(運動と逆向き)、0.80 W', check: '抵抗のジュール熱 RI²＝0.20×2.0²＝0.80 W と一致し、外からした仕事がすべて熱になったと確かめられる。' }] },
      { h: '自己誘導と相互誘導', t: 'コイルに流れる電流が変化すると、コイル自身がつくる磁束も変化します。すると、そのコイル自身に誘導起電力が生じます。これを【自己誘導】といいます。\n自己誘導による起電力は 【V＝−L ΔI/Δt】。L を【自己インダクタンス】〔H(ヘンリー)〕といい、コイルの巻き数や形、鉄心で決まります。マイナスはレンツの法則で、電流の変化を妨げる向きに起電力が生じます。だからコイルは「電流の急な変化をきらう」部品です。スイッチを切った瞬間に大きな電圧が生じて火花が飛ぶのも、このためです。\n【コイルのエネルギー】電流 i を流しているコイルに、さらに電流を増やすには、逆向きの起電力 L Δi/Δt に逆らって仕事をする必要があります。電流 0 から I まで増やす仕事を合計すると、コンデンサーの (1/2)CV² と同じ考え方(グラフの三角形の面積)で、【U＝(1/2)LI²】 になります。\n【相互誘導】2つのコイルを近くに置き、一方(1次コイル)の電流を変化させると、もう一方(2次コイル)を貫く磁束が変わり、2次コイルに起電力 V₂＝−M ΔI₁/Δt が生じます。M を【相互インダクタンス】といいます。\n【変圧器】共通の鉄心に巻いた2つのコイルでは、電圧の比は巻き数の比になります。【V₁:V₂＝N₁:N₂】。損失のない理想的な変圧器では電力が保存され、V₁I₁＝V₂I₂ です。送電では、電圧を高くして電流を小さくし、導線のジュール熱(RI²)を減らしています。',
        key: '自己誘導 V＝−L ΔI/Δt、コイルのエネルギー (1/2)LI²。変圧器は V₁:V₂＝N₁:N₂。',
        ex: [{ q: '自己インダクタンス 0.20 H のコイルに流れる電流が、0.010 s の間に一定の割合で 0 A から 3.0 A に増えた。この間に生じる自己誘導起電力の大きさと、3.0 A のときコイルにたくわえられているエネルギーを求めよ。', hint: 'ΔI/Δt＝3.0/0.010 です。', steps: ['電流の変化の速さ:ΔI/Δt＝3.0/0.010＝3.0×10² A/s。', '起電力の大きさ:V＝L ΔI/Δt＝0.20×3.0×10²＝60 V(電流の増加を妨げる向き)。', 'エネルギー:U＝(1/2)LI²＝0.5×0.20×3.0²＝0.90 J。'], a: '起電力 60 V、エネルギー 0.90 J', check: '起電力の大きさ 60 V に平均電流 1.5 A をかけ、時間 0.010 s をかけると 60×1.5×0.010＝0.90 J となり、コイルにした仕事とエネルギーが一致する。' }] },
      { h: '交流', t: '磁場の中でコイルを一定の角速度 ω で回すと、コイルを貫く磁束が Φ＝BS cos ωt のように変わり、誘導起電力 【V＝V₀ sin ωt】(V₀＝NBSω)が生じます。向きと大きさが周期的に変わる電圧・電流を【交流】といいます。家庭の交流の周波数は、東日本で 50 Hz、西日本で 60 Hz です。\n【実効値】抵抗 R に交流を流すと、電力 RI² は時間とともに変わり、平均すると (1/2)RI₀² になります。これと同じ熱を出す直流の値を【実効値】といい、【Iₑ＝I₀/√2】、Vₑ＝V₀/√2 です。家庭の「100 V」は実効値で、最大値は約 141 V です。\n【抵抗】電流と電圧は同じ位相で変化します。\n【コイル】電流の変化を妨げるので、電流は電圧より【位相が π/2 遅れ】ます。交流の流れにくさ(リアクタンス)は 【ωL】 で、振動数が高いほど流れにくくなります。\n【コンデンサー】充電・放電をくり返すことで電流が流れ、電流は電圧より【位相が π/2 進み】ます。リアクタンスは 【1/(ωC)】 で、振動数が高いほど流れやすくなります。\nコイルやコンデンサーでは、電流と電圧の位相が π/2 ずれているので、1周期で平均した消費電力は0です。エネルギーをたくわえたり返したりしているだけなのです。なお、コイルとコンデンサーをつないだ回路は、振動数 f＝1/(2π√(LC)) で電気振動をします。',
        key: '実効値＝最大値/√2。コイル:ωL、電流が π/2 遅れる。コンデンサー:1/(ωC)、電流が π/2 進む。',
        ex: [{ q: '実効値 100 V、周波数 50 Hz の交流電源に、自己インダクタンス 0.16 H のコイルだけをつないだ。コイルのリアクタンスと、流れる電流の実効値を求めよ。また、このコイルの平均の消費電力はいくらか。(π＝3.14)', hint: 'ω＝2πf。電流の実効値＝電圧の実効値÷リアクタンス。', steps: ['角周波数 ω＝2πf＝2×3.14×50＝314 rad/s。', 'リアクタンス ωL＝314×0.16≒50 Ω。', '電流の実効値 Iₑ＝Vₑ/(ωL)＝100/50＝2.0 A。', '電流と電圧の位相が π/2 ずれているので、平均の消費電力は 0 W。'], a: 'リアクタンス 約 50 Ω、電流の実効値 約 2.0 A、消費電力 0 W', check: '同じ 50 Ω でも抵抗なら 100²/50＝200 W を消費する。コイルはエネルギーを出し入れするだけなので 0 になる、というちがいが確かめられる。' }] },
      { h: 'もっと深く:電磁誘導は「ローレンツ力」で説明できる', t: '磁場の中を導体棒が動くと起電力が生じるのは、棒の中の自由電子が棒と一緒に動き、【ローレンツ力】を受けるからです。\n磁束密度 B の磁場に垂直に、長さ l の棒が速さ v で動くとします。棒の中の電荷 q は qvB の力を受けて棒の一端に集まり、棒の両端に電位差が生じます。この電位差による電場 E が qE＝qvB とつり合うまで電荷は移動するので、E＝vB、両端の電位差は El＝【vBl】 になります。これは、1秒あたりに棒が横切る磁束 ΔΦ/Δt＝B×(lv) と一致します。\nエネルギーの流れも見てみましょう。抵抗 R をつないで電流 I＝vBl/R が流れると、棒は磁場から IBl の力を【運動を妨げる向き】に受けます(レンツの法則)。棒を一定の速さで動かすには、外から同じ大きさの力を加え続ける必要があり、その仕事率は IBl×v＝(vBl)²/R＝RI² です。外力の仕事が、そのまま抵抗のジュール熱になっているのです。\nでは、コイルを動かさずに磁場の方を変化させた場合はどうでしょう。このときは電荷が動いていないので、ローレンツ力では説明できません。実は、【磁場が変化すると、そのまわりに渦を巻くような電場(誘導電場)が生じる】のです。この電場が電荷を動かし、起電力になります。どちらの場合も、結果は V＝−N ΔΦ/Δt という同じ式で表されます。\nコイルに電流を流すと、電流をつくるときに自己誘導起電力に逆らって仕事をする必要があり、その分がコイルの磁場のエネルギー【(1/2)LI²】としてたくわえられます。コンデンサーの (1/2)CV² と対になる式です。',
        key: '動く棒の起電力 vBl はローレンツ力から導ける。外力の仕事＝ジュール熱。磁場が変化すると誘導電場が生じる。コイルのエネルギーは (1/2)LI²。' },
      { h: '入試ではこう出る:レール上の導体棒と、荷電粒子の運動', t: '電磁気の後半の入試では、【レール上の導体棒】と【磁場中の荷電粒子】がとくによく出ます。\n【型1:終端速度】重力や一定の力で導体棒が動き始めると、速さが増えるにつれて誘導電流が増え、運動を妨げる力 vB²l²/R も大きくなります。やがて力がつり合い、【加速度0の一定の速さ(終端速度)】になります。「十分時間がたった後」と書かれていたら、力のつり合いの式を立てましょう。\n【型2:エネルギーで検算】終端速度で動いているとき、重力がする仕事率 mgv と、抵抗のジュール熱 RI² は等しくなります。この関係は、答えの検算にも、別の解き方にも使えます。\n【型3:速度選択器と質量分析】電場 E と磁場 B を垂直にかけた領域では、qE＝qvB を満たす速さ v＝E/B の粒子だけがまっすぐ進みます。その後、磁場だけの領域に入ると半径 r＝mv/(qB) の円運動をするので、r から質量や比電荷 q/m が分かります。\n【型4:周期は速さによらない】磁場中の円運動の周期は T＝2πm/(qB) で、速さに関係しません。サイクロトロン(加速器)は、この性質を利用しています。\nひっかけとして多いのは、①電子(負電荷)の力の向きをフレミングの左手の法則で求めたまま逆にし忘れる、②ローレンツ力が粒子に仕事をすると考えて速さを変えてしまう、③終端速度で「力の和＝0」なのに加速度を残してしまう、の3つです。',
        key: '終端速度は力のつり合い mg＝vB²l²/R。そのとき mgv＝RI²。速度選択器 v＝E/B、円運動 r＝mv/(qB)、周期 2πm/(qB) は速さによらない。',
        ex: [{ q: '鉛直に立てた2本の導体レール(間隔 0.50 m)が、上端で抵抗 0.10 Ω につながっている。レール面に垂直に磁束密度 0.40 T の一様な磁場がかかっている。質量 0.020 kg の導体棒をレールに水平に置いて静かにはなすと、やがて一定の速さで落下した。この速さと、そのときの抵抗での消費電力を求めよ。(g＝9.8 m/s²、レールと棒の抵抗・摩擦は無視)', hint: '一定の速さ(終端速度)では、重力と電流が受ける力がつり合います。', steps: ['速さ v のとき誘導起電力は vBl、電流は I＝vBl/R。', '棒が受ける上向きの力は IBl＝vB²l²/R。つり合い:mg＝vB²l²/R。', 'v＝mgR/(B²l²)＝0.020×9.8×0.10/(0.40²×0.50²)＝0.0196/0.040＝0.49 m/s。', '電流 I＝0.49×0.40×0.50/0.10＝0.98 A、消費電力 RI²＝0.10×0.98²≒0.096 W。'], a: '速さ 0.49 m/s、消費電力 約 0.096 W', check: '重力の仕事率 mgv＝0.020×9.8×0.49≒0.096 W と、ジュール熱が一致する。' }, { q: '強さ 2.0×10⁴ V/m の電場と、それに垂直な磁束密度 0.10 T の磁場がかかった領域を、陽子がまっすぐ通りぬけた。陽子の速さを求めよ。また、この陽子が磁束密度 0.10 T の磁場だけの領域に垂直に入ったときの円運動の半径を求めよ。(陽子の質量 1.67×10⁻²⁷ kg、電気量 1.6×10⁻¹⁹ C)', hint: 'まっすぐ進むのは、静電気力とローレンツ力がつり合うときです。', steps: ['つり合い:qE＝qvB より v＝E/B＝2.0×10⁴/0.10＝2.0×10⁵ m/s。', '磁場だけの領域では、ローレンツ力が向心力:m v²/r＝qvB より r＝mv/(qB)。', 'r＝1.67×10⁻²⁷×2.0×10⁵/(1.6×10⁻¹⁹×0.10)＝3.34×10⁻²²/1.6×10⁻²⁰≒2.1×10⁻² m。'], a: '速さ 2.0×10⁵ m/s、半径 約 2.1×10⁻² m(約 2.1 cm)', check: '速さは電荷 q によらない(q が両辺で消える)。半径は質量に比例するので、質量のちがう粒子が分けられる。' }] }
    ],
    faq: [['フレミングの左手の法則と右ねじの法則は、どう使い分けるの?', '右ねじの法則は「電流がつくる磁場の向き」を決めるときに使います。フレミングの左手の法則は「磁場の中の電流(または動く電荷)が受ける力の向き」を決めるときに使います。\n問題で「何の向きを聞かれているか」を先に確かめると、迷わなくなります。電磁誘導の向きは、レンツの法則(変化を妨げる向き)で決めるのが確実です。'],
      ['ローレンツ力は仕事をしないのに、モーターはなぜ回るの?', '1個の電子が受けるローレンツ力は速度に垂直なので、電子に仕事はしません。モーターで導線を動かしているのは、電子が導線の中にとどまるために、導線(の陽イオン)に力をおよぼしているからです。\nエネルギーの出どころは電池(電源)です。導線が動くと誘導起電力が生じて電流を妨げるので、電源はそれに逆らって仕事をし、その分が力学的な仕事になります。'],
      ['実効値をわざわざ使うのはなぜ?', '交流の電圧や電流は、時間とともに +と− を行き来するので、ふつうに平均すると0になってしまいます。それでは「どれだけ熱を出せるか」が分かりません。\n実効値は「同じ熱を出す直流の値」なので、電力を P＝VₑIₑ のように直流と同じ式で計算できます。電気器具の表示が実効値なのは、このためです。'],
      ['V＝vBl と V＝N ΔΦ/Δt は別の法則なの?', '同じ現象を2つの見方で書いたものです。棒が動く場合、1秒間に棒が横切る面積は lv なので、横切る磁束は ΔΦ/Δt＝Blv となり、vBl と一致します。\n棒が動く場合はローレンツ力、磁場が変化する場合は誘導電場が原因ですが、どちらも「磁束の変化の速さ」で起電力が決まる、とまとめられます。']],
    drill: [
      { lv: 1, q: '磁束密度 0.20 T の一様な磁場の中に、磁場と垂直に長さ 0.30 m の導線を置き、5.0 A の電流を流した。導線が受ける力の大きさを求めよ。', a: '0.30 N', exp: '電流が磁場から受ける力は F＝IBl です(電流と磁場が垂直なとき)。\nF＝5.0×0.20×0.30＝0.30 N。\n向きはフレミングの左手の法則で決まり、電流と磁場の両方に垂直です。電流と磁場が平行なら力は 0 になります。' },
      { lv: 1, q: '巻数 100 のコイルを貫く磁束が、0.20 s の間に一定の割合で 3.0×10⁻³ Wb から 1.0×10⁻³ Wb に減少した。コイルに生じる誘導起電力の大きさを求めよ。', a: '1.0 V', exp: 'ファラデーの電磁誘導の法則 V＝N|ΔΦ/Δt| を使います。\n磁束の変化は ΔΦ＝1.0×10⁻³−3.0×10⁻³＝−2.0×10⁻³ Wb。\nV＝100×2.0×10⁻³/0.20＝1.0 V。誘導電流は、減っていく磁束を補う向き(元の磁束と同じ向きの磁場をつくる向き)に流れます。' },
      { lv: 2, q: '半径 0.10 m、巻数 50 の円形コイルに 2.0 A の電流を流した。コイルの中心の磁場の強さ H と磁束密度 B を求めよ。(μ₀＝4π×10⁻⁷ N/A²、π＝3.14)', a: 'H＝5.0×10² A/m、B≒6.3×10⁻⁴ T', exp: '円形電流の中心の磁場は、1巻きあたり H＝I/(2r) で、N 巻きならその N 倍です。\nH＝NI/(2r)＝50×2.0/(2×0.10)＝500 A/m。\nB＝μ₀H＝4×3.14×10⁻⁷×500≒6.3×10⁻⁴ T。\n直線電流の I/(2πr) と混同しやすいので、円形電流には π が入らないことを確認します。' },
      { lv: 2, q: '一次コイルの巻数 500、二次コイルの巻数 25 の理想的な変圧器の一次側に、実効値 100 V の交流電圧をかけた。二次側に 10 Ω の抵抗をつないだとき、二次側の電圧・二次側の電流・一次側の電流(いずれも実効値)を求めよ。', a: '二次電圧 5.0 V、二次電流 0.50 A、一次電流 0.025 A', exp: '電圧の比は巻数の比:V₂＝100×25/500＝5.0 V。\n二次側の電流 I₂＝V₂/R＝5.0/10＝0.50 A、電力は 5.0×0.50＝2.5 W。\n理想的な変圧器では電力が保存されるので、V₁I₁＝V₂I₂ より I₁＝2.5/100＝0.025 A。\n電圧を下げると電流は大きくなる(巻数の逆比)ことも確かめましょう。' },
      { lv: 3, q: '自己インダクタンス 1.0×10⁻³ H のコイルと、電気容量 1.0×10⁻⁹ F のコンデンサーを直列につなぎ、交流電源を接続した。回路に流れる電流が最も大きくなる(共振する)周波数を求めよ。(π＝3.14)', a: '約 1.6×10⁵ Hz', exp: 'コイルのリアクタンスは ωL、コンデンサーのリアクタンスは 1/(ωC) で、両者の電圧は逆位相になって打ち消し合います。\nωL＝1/(ωC) のとき打ち消し合いが完全になり、電流が最大になります(共振)。ω＝1/√(LC)、f＝1/(2π√(LC))。\n√(LC)＝√(1.0×10⁻¹²)＝1.0×10⁻⁶ なので f＝1/(6.28×10⁻⁶)≒1.6×10⁵ Hz。\nこれは LC 回路の電気振動の周波数と同じで、ラジオの選局はこのしくみを利用しています。' },
      { lv: 3, q: '陽子(質量 1.67×10⁻²⁷ kg、電気量 1.6×10⁻¹⁹ C)が、磁束密度 0.50 T の一様な磁場に垂直に入り、等速円運動をした。円運動の周期を求めよ。また、陽子の速さを2倍にすると、半径と周期はそれぞれ何倍になるか。(π＝3.14)', a: '周期 約 1.3×10⁻⁷ s。半径は2倍、周期は変わらない(1倍)。', exp: 'ローレンツ力が向心力なので m v²/r＝qvB、r＝mv/(qB)。周期は T＝2πr/v＝2πm/(qB) で、v が消えます。\nT＝2×3.14×1.67×10⁻²⁷/(1.6×10⁻¹⁹×0.50)＝1.049×10⁻²⁶/8.0×10⁻²⁰≒1.3×10⁻⁷ s。\n速さを2倍にすると、半径 r は v に比例して2倍。円周も2倍になりますが速さも2倍なので、1周の時間は変わりません。' }
    ],
    terms: [['磁束密度', 'B＝μH。単位 T(テスラ)'], ['磁束', 'Φ＝BS。面を貫く磁力線の量(Wb)'], ['ローレンツ力', '動く荷電粒子が磁場から受ける力 qvB'], ['電磁誘導', '磁束の変化によって起電力が生じる現象'], ['レンツの法則', '誘導電流は磁束の変化を妨げる向きに流れる'], ['自己インダクタンス', 'V＝−L ΔI/Δt の L(H)'], ['実効値', '同じ熱を出す直流の値。最大値の 1/√2'], ['リアクタンス', '交流の流れにくさ。コイル ωL、コンデンサー 1/(ωC)']],
    miss: ['磁束が大きいほど誘導起電力が大きいと考える。→ 起電力を決めるのは磁束の「変化の速さ」です。磁束が一定なら、どんなに大きくても起電力は0。', '電子(負の電荷)の力の向きを、正の電荷と同じに決める。→ 電子は電流と逆向きに動くので、左手の法則で求めた向きを反対にします。', 'ローレンツ力で粒子の速さが変わると考える。→ 力はいつも速度に垂直なので仕事をせず、速さは一定です。', 'コイルとコンデンサーの位相の遅れ・進みを逆に覚える。→ コイルは電流の変化を妨げるので電流が「遅れる」、と理由とセットで覚えます。', '家庭の 100 V を最大値と考える。→ 表示は実効値で、最大値は √2 倍の約 141 V です。'],
    sum: ['直線電流 H＝I/(2πr)、円形の中心 I/(2r)、ソレノイド nI。B＝μH。', '電流が受ける力 F＝IBL、荷電粒子が受けるローレンツ力 f＝qvB。磁場中で r＝mv/(qB) の円運動。', '電磁誘導 V＝−N ΔΦ/Δt、向きはレンツの法則。導体棒は V＝vBL。', '自己誘導 V＝−L ΔI/Δt、エネルギー (1/2)LI²。変圧器は電圧比＝巻き数比。', '交流の実効値＝最大値/√2。コイル ωL(電流が遅れる)、コンデンサー 1/(ωC)(電流が進む)。'],
    next: '次は『原子:光電効果・原子模型・原子核(物理)』へ。電場や磁場で電子の運動を調べる方法は、原子の世界を探る実験でも使われます。'
  };

  // ===== 原子 =====
  L.p4_atom = {
    goal: '光電効果から光の粒子性を、電子線の回折から物質の波動性を説明でき、ボーアの原子模型で水素原子の光を計算し、原子核の崩壊と半減期の計算ができるようになる。',
    intro: '光は波だと、前の単元で学びました。ところが20世紀のはじめ、光を金属に当てる実験で、波では説明できない結果が出ました。逆に、粒子だと思われていた電子が、波のように干渉することも分かりました。小さな世界では「波か粒子か」のどちらか一方ではなく、両方の性質をもつのです。この単元では、その考え方(量子論)の入り口と、原子核の世界を学びます。',
    pre: '【波の基本式】光の速さ c＝νλ(c≒3.0×10⁸ m/s、ν は振動数)。光の色は振動数(波長)で決まり、紫は振動数が大きく波長が短く、赤はその逆です。\n【電子ボルト eV】電子を 1 V の電位差で加速したときに得るエネルギーを 1 eV といいます。1 eV＝1.6×10⁻¹⁹ J。原子の世界のエネルギーは J では小さすぎるので、この単位を使います。\n【運動量と運動エネルギー】p＝mv、K＝(1/2)mv²。2つを組み合わせると K＝p²/(2m)、p＝√(2mK) です。\n【等速円運動とクーロン力】電子が原子核のまわりを回るモデルでは、クーロン力 ke²/r² が向心力 m v²/r になります(『力学の発展』『電気』で学習)。\n【指数の計算】(1/2)³＝1/8、(1/2)⁴＝1/16。半減期の計算で使います。',
    secs: [
      { h: '光電効果と光子', t: '金属に光を当てると、表面から電子が飛び出すことがあります。これを【光電効果】、飛び出す電子を【光電子】といいます。\n実験で分かった事実:①ある振動数(【限界振動数 ν₀】)より小さい振動数の光では、どんなに強い光を当てても電子は出ない ②飛び出す電子の最大の運動エネルギーは、光の【振動数】で決まり、光の強さによらない ③光を強くすると、飛び出す電子の【数】が増える ④弱い光でも、当てるとすぐに電子が出る。\nなぜ波では説明できないのか:光が波なら、強い光(振幅が大きい)ほどエネルギーが大きいので、振動数に関係なく、強くすれば電子が出るはずです。また、弱い光ならエネルギーがたまるまで時間がかかるはずです。①②④はこの予想と合いません。\nアインシュタインは、光は 【E＝hν】 のエネルギーをもつ粒(【光子】)の集まりだと考えました。h は【プランク定数】(約 6.6×10⁻³⁴ J·s)です。電子は光子1個を吸収し、そのエネルギーのうち、金属から出るのに必要な最小のエネルギー(【仕事関数 W】)を使って飛び出します。だから 【K₀＝hν−W】。光の強さは光子の数なので、強くしても1個のエネルギーは変わらず、電子の数だけが増えます。\nhν＜W なら電子は出られないので、限界振動数は 【hν₀＝W】 です。光電子の運動エネルギーは、逆向きの電圧をかけて電流が0になる電圧(阻止電圧 V₀)から eV₀＝K₀ として測れます。\nK₀ を ν に対してグラフにすると、傾き h の直線になり、どの金属でも傾きは同じです。ν 軸との交点が ν₀、縦軸の切片(延長)が −W です。',
        key: '光子のエネルギー E＝hν。光電子の最大運動エネルギー K₀＝hν−W は振動数で決まり、強さは電子の数を決める。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="光電子の最大運動エネルギーと振動数のグラフ。傾きがプランク定数h、横軸との交点が限界振動数、縦軸の切片が仕事関数のマイナス"><line x1="20" y1="90" x2="205" y2="90" class="ax"/><line x1="40" y1="140" x2="40" y2="10" class="ax"/><line x1="80" y1="90" x2="190" y2="25" class="cv"/><line x1="40" y1="114" x2="80" y2="90" class="dash"/><circle cx="80" cy="90" r="3" class="pt"/><circle cx="40" cy="114" r="3" class="pt"/><text x="46" y="18">K₀</text><text x="184" y="104">ν</text><text x="74" y="104">ν₀</text><text x="6" y="118">−W</text><text x="96" y="40">傾き＝h</text><text x="96" y="130">K₀＝hν−W</text><text x="96" y="146">傾きは金属によらない</text></svg>',
        ex: [{ q: '仕事関数 2.0 eV の金属に、光子1個のエネルギーが 3.0 eV の光を当てた。光電子の最大運動エネルギー〔eV と J〕、阻止電圧、この金属の限界振動数を求めよ。(h＝6.6×10⁻³⁴ J·s、1 eV＝1.6×10⁻¹⁹ J)', hint: 'K₀＝hν−W は eV のまま計算できます。', steps: ['K₀＝hν−W＝3.0−2.0＝1.0 eV。', 'J に直すと 1.0×1.6×10⁻¹⁹＝1.6×10⁻¹⁹ J。', '阻止電圧:eV₀＝K₀ より V₀＝1.0 V。', '限界振動数:hν₀＝W より ν₀＝2.0×1.6×10⁻¹⁹/6.6×10⁻³⁴＝3.2×10⁻¹⁹/6.6×10⁻³⁴≒4.8×10¹⁴ Hz。'], a: 'K₀＝1.0 eV(1.6×10⁻¹⁹ J)、阻止電圧 1.0 V、限界振動数 約 4.8×10¹⁴ Hz', check: 'ν₀ に対応する波長 c/ν₀＝3.0×10⁸/4.8×10¹⁴≒6.2×10⁻⁷ m は可視光の範囲で、これより波長の短い光で電子が出る、という結果は筋が通る。' }] },
      { h: '光の粒子性と X 線', t: '光子はエネルギーだけでなく、運動量ももちます。波長 λ の光子の運動量は 【p＝h/λ】(＝hν/c)です。\nこれを確かめたのが【コンプトン効果】です。X 線を物質に当てると、散乱された X 線の中に、もとより波長の長いものがふくまれていました。光子が電子と衝突して、エネルギーと運動量の一部を電子に渡したと考えると、うまく説明できます。光子にも運動量保存とエネルギー保存が成り立つのです。\n【X 線】は、高い電圧で加速した電子を金属(陽極)に当てると出る、波長の短い電磁波です。加速電圧 V の電子の運動エネルギー eV がすべて1個の光子になったときが、最も波長の短い X 線になります。eV＝hc/λ₀ より 【λ₀＝hc/(eV)】(最短波長)。\nX 線は波長が原子の間隔と同じくらいなので、結晶に当てると回折・干渉します。これを使って結晶の構造を調べられます(ブラッグの条件 2d sinθ＝nλ)。\nこのように、光は干渉する(波の性質)と同時に、エネルギーと運動量のかたまりとしてふるまう(粒子の性質)ことが分かりました。これを光の【二重性】といいます。',
        key: '光子の運動量 p＝h/λ。光は波と粒子の両方の性質をもつ(二重性)。' },
      { h: '物質波(ド・ブロイ波)', t: '光が粒子の性質ももつなら、電子のような粒子も波の性質をもつのではないか。ド・ブロイはこう考え、光子の p＝h/λ を逆に読んで、運動量 p＝mv の粒子に波長 【λ＝h/(mv)】 を対応させました。この波を【物質波(ド・ブロイ波)】といいます。\nふだんの物体では、h がとても小さいので、波長は短すぎて観測できません。たとえば 0.15 kg のボールが 40 m/s で飛んでも、波長は約 10⁻³⁴ m です。\nところが電子は質量がとても小さいので、波長が原子の間隔ほどになります。実際に電子線を結晶に当てると、X 線と同じような回折の模様が現れ、電子が波の性質をもつことが確かめられました。電子顕微鏡は、この電子の波を使って、光より細かいものを見る装置です。\n電圧 V で加速した電子の場合:運動エネルギー eV＝p²/(2m) より p＝√(2meV)、波長は 【λ＝h/√(2meV)】 です。電圧を高くするほど、波長は短くなります。',
        key: '物質波の波長 λ＝h/(mv)。電圧 V で加速した電子なら λ＝h/√(2meV)。',
        ex: [{ q: '静止していた電子を 150 V の電位差で加速した。電子のド・ブロイ波長を求めよ。(電子の質量 9.1×10⁻³¹ kg、電気素量 1.6×10⁻¹⁹ C、h＝6.6×10⁻³⁴ J·s)', hint: 'まず運動エネルギー eV から運動量 p＝√(2meV) を求めます。', steps: ['運動エネルギー:eV＝1.6×10⁻¹⁹×150＝2.4×10⁻¹⁷ J。', '2m×eV＝2×9.1×10⁻³¹×2.4×10⁻¹⁷≒4.37×10⁻⁴⁷。', 'p＝√(4.37×10⁻⁴⁷)≒6.6×10⁻²⁴ kg·m/s。', 'λ＝h/p＝6.6×10⁻³⁴/6.6×10⁻²⁴≒1.0×10⁻¹⁰ m。'], a: '約 1.0×10⁻¹⁰ m', check: 'この波長は結晶中の原子の間隔(10⁻¹⁰ m 程度)と同じくらいなので、結晶で回折が起こるという実験事実と合う。' }] },
      { h: 'ボーアの原子模型と水素原子のスペクトル', t: 'ラザフォードの実験で、原子の中心に小さな原子核があり、そのまわりを電子が回っていることが分かりました。しかし、昔の電磁気学では、回る電子は光を出してエネルギーを失い、原子核に落ちてしまうはずです。また、水素が出す光は、決まった波長だけのとびとびの線(線スペクトル)でした。\nボーアは2つの仮説を立てました。【量子条件】電子は、軌道の円周が電子の物質波の波長の整数倍(2πr＝nλ)になる軌道だけを回れる。λ＝h/(mv) を入れると 【mvr＝nh/(2π)】(n＝1, 2, 3, …)。このとき電子は光を出さない(【定常状態】)。【振動数条件】電子がエネルギー E の状態から E′ の状態へ移るとき、その差のエネルギーの光子を1個出す。【hν＝E−E′】。\n水素原子の場合:クーロン力が向心力なので m v²/r＝ke²/r²。これと量子条件を連立すると、軌道半径は n² に比例し(n＝1 で約 5.3×10⁻¹¹ m)、エネルギー(運動エネルギーとクーロン力の位置エネルギーの和)は 【Eₙ＝−13.6/n² eV】 となります。\nn＝1 の最もエネルギーの低い状態を【基底状態】、それより上を【励起状態】といいます。エネルギーがマイナスなのは、電子が原子核に束縛されていることを表します。13.6 eV を与えると電子は原子から離れます(電離)。\n電子が n＝3, 4, … から n＝2 へ移るとき出る光の系列(バルマー系列)は可視光をふくみ、n＝1 へ移る系列(ライマン系列)は紫外線です。原子ごとにエネルギー準位がちがうので、出す光の波長も原子ごとに決まっています。',
        key: '量子条件 mvr＝nh/(2π)、振動数条件 hν＝E−E′。水素原子 Eₙ＝−13.6/n² eV。',
        fig: '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="水素原子のエネルギー準位。n＝3からn＝2への移り変わりで1.89eV、n＝2からn＝1で10.2eVの光子が出る"><line x1="40" y1="15" x2="140" y2="15" class="dash"/><line x1="40" y1="28" x2="140" y2="28" class="ax"/><line x1="40" y1="44" x2="140" y2="44" class="ax"/><line x1="40" y1="130" x2="140" y2="130" class="ax"/><line x1="70" y1="28" x2="70" y2="43" class="cv2"/><polyline points="67,39 70,44 73,39" class="cv2"/><line x1="128" y1="44" x2="128" y2="129" class="cv"/><polyline points="124,123 128,130 132,123" class="cv"/><text x="2" y="18">0</text><text x="2" y="31">−1.51</text><text x="2" y="48">−3.4</text><text x="2" y="133">−13.6</text><text x="148" y="18">n＝∞</text><text x="148" y="31">n＝3</text><text x="148" y="48">n＝2</text><text x="148" y="133">n＝1</text><text x="44" y="74">3→2:1.89 eV</text><text x="44" y="92">2→1:10.2 eV</text><text x="44" y="146">単位 eV</text></svg>',
        ex: [{ q: '水素原子の電子が n＝3 から n＝2 の状態に移るときに出る光の、光子のエネルギーと波長を求めよ。(Eₙ＝−13.6/n² eV、h＝6.6×10⁻³⁴ J·s、c＝3.0×10⁸ m/s、1 eV＝1.6×10⁻¹⁹ J)', hint: 'hν＝E₃−E₂ を求め、λ＝hc/E で波長にします。', steps: ['E₃＝−13.6/9≒−1.51 eV、E₂＝−13.6/4＝−3.4 eV。', '光子のエネルギー:E₃−E₂＝13.6×(1/4−1/9)＝13.6×5/36≒1.89 eV。', 'J に直すと 1.89×1.6×10⁻¹⁹≒3.02×10⁻¹⁹ J。', 'λ＝hc/E＝6.6×10⁻³⁴×3.0×10⁸/3.02×10⁻¹⁹≒6.6×10⁻⁷ m。'], a: '約 1.9 eV、波長 約 6.6×10⁻⁷ m(赤い光)', check: '可視光(3.8×10⁻⁷〜7.7×10⁻⁷ m)の赤い側に入り、バルマー系列が可視光をふくむという事実と一致する。' }] },
      { h: '原子核と放射線', t: '原子核は、正の電荷をもつ【陽子】と、電荷をもたない【中性子】からできています(まとめて核子という)。陽子の数を【原子番号 Z】、核子の数を【質量数 A】といい、元素記号の左上に A、左下に Z を書いて表します(例 ⁴₂He)。原子番号が同じで質量数がちがう原子を【同位体】といいます。\n陽子どうしは電気的に反発するのに原子核がまとまっているのは、核子どうしに、ごく近い距離ではたらく強い引力(【核力】)があるからです。\n不安定な原子核は、放射線を出して別の原子核に変わります(【放射性崩壊】)。【α崩壊】α線(ヘリウム原子核 ⁴₂He)を出し、Z が2、A が4減る。【β崩壊】原子核の中の中性子が陽子に変わり、β線(電子)を出す。Z が1増え、A は変わらない。【γ線】崩壊の後などに出る波長の短い電磁波で、Z も A も変わらない。\n放射線が物質を通りぬける力(透過力)は α＜β＜γ の順に大きく、α線は紙1枚、β線は数 mm のアルミニウム板で止まりますが、γ線を止めるには厚い鉛やコンクリートが必要です。原子から電子をはじき出す力(電離作用)は、逆に α が最も強いです。\n単位:【Bq(ベクレル)】1秒あたりに崩壊する原子核の数(放射能の強さ)。【Gy(グレイ)】物質 1 kg が吸収したエネルギー〔J〕。【Sv(シーベルト)】人体への影響を考えに入れた量。\n原子核の質量は、ばらばらの核子の質量の和より少し小さくなります(【質量欠損】Δm)。その分のエネルギー 【E＝Δmc²】 が【結合エネルギー】です。ウランの核分裂や、水素の核融合で大きなエネルギーが出るのは、反応の前後で質量が減るからです。',
        key: 'α崩壊:Z−2、A−4。β崩壊:Z＋1、A不変。γ線:変化なし。核反応では Z と A の和が保存され、質量欠損 Δm がエネルギー Δmc² になる。',
        ex: [{ q: 'ウラン ²³⁸₉₂U は、α崩壊とβ崩壊をくり返して、最後に安定な鉛 ²⁰⁶₈₂Pb になる。α崩壊とβ崩壊は、それぞれ何回起こるか。', hint: '質量数を変えるのは α崩壊だけです。先に α の回数を決めます。', steps: ['質量数の減少:238−206＝32。α崩壊1回で4減るので、α崩壊は 32÷4＝8 回。', 'α崩壊8回で原子番号は 2×8＝16 減り、92−16＝76 になる。', '実際は 82 なので、増えた 82−76＝6 はβ崩壊による。β崩壊1回で1増えるので6回。'], a: 'α崩壊 8 回、β崩壊 6 回', check: '原子番号:92−2×8＋1×6＝82、質量数:238−4×8＝206 で、どちらも鉛と一致する。' }] },
      { h: '半減期', t: '放射性の原子核がいつ崩壊するかは、1個ずつは予測できません。しかし、たくさん集まると、一定の時間ごとに【残っている数の半分】が崩壊します。この時間を【半減期 T】といいます。\nはじめの数を N₀ とすると、時間 t 後に崩壊せずに残っている数は 【N＝N₀(1/2)^(t/T)】 です。半減期1回で 1/2、2回で 1/4、3回で 1/8 になります。「半減期が2回たつと全部なくなる」わけではないことに注意しましょう。\n半減期は原子核の種類で決まり、温度や圧力、化学変化には影響されません。たとえばヨウ素131は約8日、炭素14は約5730年、ウラン238は約45億年です。\nこの性質を使ったのが【年代測定】です。生物は生きている間、大気中と同じ割合で炭素14を取りこみますが、死ぬと取りこみが止まり、炭素14は半減期約5730年で減っていきます。残っている炭素14の割合を測れば、死んでからの年数が分かります。\n計算のコツ:まず「もとの何分の1か」を (1/2) の何乗かに直し、その指数×半減期で時間を求めます。2の累乗(2, 4, 8, 16, 32)をすぐ思い出せるようにしておきましょう。',
        key: 'N＝N₀(1/2)^(t/T)。半減期 n 回で (1/2)ⁿ。半減期は原子核の種類で決まり、温度などで変わらない。',
        ex: [{ q: '遺跡から出た木材にふくまれる炭素14の割合が、現在の生きている木の 1/4 だった。この木が切られてから、およそ何年たったか。(炭素14の半減期は 5730 年とする)', hint: '1/4 は (1/2) の何乗かを考えます。', steps: ['1/4＝(1/2)² なので、半減期が2回たった。', '経過時間＝2×5730＝11460 年。', '有効数字を考えて、約 1.1×10⁴ 年。'], a: '約 1.1×10⁴ 年(約 11460 年)', check: '1回目の半減期(5730年)で 1/2、2回目(11460年)で 1/4 になる。順に数えても一致する。' }] },
      { h: 'もっと深く:核子1個あたりの結合エネルギーと、核分裂・核融合', t: '原子核の質量は、ばらばらの陽子と中性子の質量の和より小さく、その差(質量欠損 Δm)に相当するエネルギー Δmc² が【結合エネルギー】です。結合エネルギーは「原子核をばらばらにするのに必要なエネルギー」であり、同時に「核子が集まって原子核になるときに放出されるエネルギー」でもあります。\n原子核の計算では、質量を【原子質量単位 u】(1 u≒1.66×10⁻²⁷ kg)で、エネルギーを MeV(1 MeV＝1.6×10⁻¹³ J)で表すと便利です。1 u の質量に相当するエネルギーは約 931 MeV です。質量欠損が 0.0300 u なら、結合エネルギーは約 28 MeV と、すぐに計算できます。\n原子核の安定さを比べるには、結合エネルギーそのものではなく、【核子1個あたりの結合エネルギー】(結合エネルギー÷質量数)を使います。これを質量数に対してグラフにすると、軽い原子核では急に増え、【鉄(質量数 56 付近)で最大(約 8.8 MeV)】になり、それより重い原子核ではゆるやかに減っていきます。\nこのグラフから、エネルギーが取り出せる2つの道が分かります。①ウランのような重い原子核が2つに割れる【核分裂】では、分裂後の原子核の方が核子1個あたりの結合エネルギーが大きい(より安定)ので、その差のエネルギーが出ます。②水素やヘリウムのような軽い原子核がくっつく【核融合】でも、より安定な原子核になるのでエネルギーが出ます。どちらも、鉄に近づく向きの反応です。\n核反応では、反応の前後で【質量数の和と電荷(原子番号)の和】が保存されます。反応式の空欄を埋める問題は、この2つの保存で解けます。たとえば ²³⁵₉₂U＋¹₀n → ¹⁴¹₅₆Ba＋⁹²₃₆Kr＋(  )¹₀n では、質量数 236＝141＋92＋x から x＝3 です。\n放出されるエネルギーは「反応前の質量の和−反応後の質量の和」に c² をかけたもの、つまり結合エネルギーの増加分です。ウラン1回の核分裂では約 200 MeV と、化学反応(数 eV)の数千万倍のエネルギーが出ます。',
        key: '1 u≒931 MeV。核子1個あたりの結合エネルギーは鉄付近で最大。核分裂も核融合も鉄に近づく向きでエネルギーが出る。核反応では質量数と電荷が保存。' },
      { h: '入試ではこう出る:光電効果のグラフと、エネルギー準位', t: '原子分野の入試では、【グラフを読む問題】と【エネルギー準位の計算】がよく出ます。式そのものは少ないので、グラフの意味を説明できるかが勝負です。\n【型1:Kₘₐₓ−ν グラフ】光電子の最大運動エネルギー Kₘₐₓ を、当てた光の振動数 ν に対してグラフにすると、Kₘₐₓ＝hν−W より直線になります。【傾きがプランク定数 h】、横軸との交点が限界振動数 ν₀、縦軸の切片(延長)が −W です。金属を変えると W が変わり、平行な別の直線になります(傾きは同じ h)。\n【型2:阻止電圧の測定】実験では Kₘₐₓ を直接ではなく、阻止電圧 V₀ で測ります(eV₀＝Kₘₐₓ)。2つの振動数での V₀ が与えられたら、e(V₀₂−V₀₁)＝h(ν₂−ν₁) から h が求められます。\n【型3:光電流−電圧グラフ】光を強くすると、光子の数が増えて【飽和電流は大きくなるが、阻止電圧は変わらない】。振動数を大きくすると、阻止電圧の大きさが大きくなります。このちがいは頻出の正誤問題です。\n【型4:エネルギー準位】水素原子で、n＝4 の状態から下の準位へ移るときに出る光は、4→3、4→2、4→1、3→2、3→1、2→1 の【6本】です(n の状態からは n(n−1)/2 本)。最も波長が短いのは、エネルギー差が最大の遷移です。\nひっかけとして多いのは、①光を強くすれば光電子のエネルギーが増えると考える、②eV と J の換算(1 eV＝1.6×10⁻¹⁹ J)を忘れる、③エネルギー差が大きいほど波長も長いと逆に考える、の3つです。',
        key: 'Kₘₐₓ−ν グラフの傾きは h、横軸切片は ν₀。光を強くしても阻止電圧は変わらない。n の状態から出る光は n(n−1)/2 本。',
        ex: [{ q: 'ある金属に振動数 6.0×10¹⁴ Hz の光を当てると阻止電圧は 0.50 V、8.0×10¹⁴ Hz の光を当てると 1.3 V だった。このデータからプランク定数と、金属の仕事関数〔eV〕を求めよ。(電気素量 1.6×10⁻¹⁹ C)', hint: 'eV₀＝hν−W を2つの振動数で書いて、引き算します。', steps: ['eV₀＝hν−W より、2つの式は e×0.50＝h×6.0×10¹⁴−W、e×1.3＝h×8.0×10¹⁴−W。', '引き算すると e×0.80＝h×2.0×10¹⁴ より h＝1.6×10⁻¹⁹×0.80/2.0×10¹⁴＝6.4×10⁻³⁴ J·s。', 'W＝h×6.0×10¹⁴−e×0.50＝3.84×10⁻¹⁹−0.80×10⁻¹⁹＝3.04×10⁻¹⁹ J。', 'eV に直すと 3.04×10⁻¹⁹/1.6×10⁻¹⁹≒1.9 eV。'], a: 'プランク定数 6.4×10⁻³⁴ J·s、仕事関数 約 1.9 eV', check: 'もう一方の式でも W＝6.4×10⁻³⁴×8.0×10¹⁴−1.3×1.6×10⁻¹⁹＝5.12×10⁻¹⁹−2.08×10⁻¹⁹＝3.04×10⁻¹⁹ J で一致する。h も実際の値 6.6×10⁻³⁴ J·s に近い。' }, { q: '水素原子の電子が n＝4 の状態にある。ここから下の準位へ移るときに出る可能性のある光は何種類か。また、その中で最も波長の短い光の波長を求めよ。(Eₙ＝−13.6/n² eV、h＝6.6×10⁻³⁴ J·s、c＝3.0×10⁸ m/s、1 eV＝1.6×10⁻¹⁹ J)', hint: '最も波長が短いのは、エネルギー差が最も大きい遷移です。', steps: ['遷移は 4→3、4→2、4→1、3→2、3→1、2→1 の6通り(4×3/2＝6)。', 'エネルギー差が最大なのは 4→1:ΔE＝13.6×(1−1/16)＝12.75 eV。', 'J に直すと 12.75×1.6×10⁻¹⁹＝2.04×10⁻¹⁸ J。', 'λ＝hc/ΔE＝6.6×10⁻³⁴×3.0×10⁸/2.04×10⁻¹⁸≒9.7×10⁻⁸ m。'], a: '6種類、最短波長 約 9.7×10⁻⁸ m(紫外線、ライマン系列)', check: '可視光(約 4×10⁻⁷〜8×10⁻⁷ m)より短く、n＝1 へ移る系列が紫外線であることと合う。' }] }
    ],
    faq: [['光は結局、波なの? 粒子なの?', 'どちらか一方ではなく、両方の性質をもちます。干渉や回折のように「広がって重なり合う」ときは波として、光電効果やコンプトン効果のように「物質とエネルギーをやりとりする」ときは粒子(光子)としてふるまいます。\n電子のような粒子も同じで、波の性質をもちます。この考え方が、現代の量子力学の出発点になっています。'],
      ['水素原子のエネルギーがマイナスなのはなぜ?', '電子が原子核から無限に離れて止まっている状態を、エネルギー0と決めているからです。原子核に引きつけられている電子は、そこから外に出るのにエネルギーが必要なので、0より低いマイナスの値になります。\n基底状態の −13.6 eV は、「13.6 eV を与えれば電子を原子から引き離せる」という意味です。'],
      ['半減期が1年の物質は、2年たつと全部なくなるの?', 'なくなりません。半減期ごとに「そのとき残っている数の半分」が崩壊するので、1年後に 1/2、2年後に 1/4、3年後に 1/8 …と、どんどん少なくなりながら残り続けます。\n「最初の量の半分ずつ減る」と考えるとまちがえます。'],
      ['β崩壊で出てくる電子は、もともと原子核の中にあったの?', 'いいえ。原子核の中に電子があるわけではありません。β崩壊では、原子核の中の中性子1個が陽子に変わり、そのとき電子(と反ニュートリノ)が新しく生まれて飛び出します。\nだから β崩壊では、質量数は変わらず、陽子が1個増えるので原子番号が1増えます。']],
    drill: [
      { lv: 1, q: '波長 5.0×10⁻⁷ m の光の光子1個のエネルギーを、J と eV で求めよ。(h＝6.6×10⁻³⁴ J·s、c＝3.0×10⁸ m/s、1 eV＝1.6×10⁻¹⁹ J)', a: '約 4.0×10⁻¹⁹ J、約 2.5 eV', exp: '光子のエネルギーは E＝hν＝hc/λ です。\nE＝6.6×10⁻³⁴×3.0×10⁸/5.0×10⁻⁷＝3.96×10⁻¹⁹≒4.0×10⁻¹⁹ J。\neV に直すと 3.96×10⁻¹⁹/1.6×10⁻¹⁹≒2.5 eV。可視光の光子はおよそ 2〜3 eV と覚えておくと、検算に使えます。' },
      { lv: 1, q: 'ラジウム ²²⁶₈₈Ra が α崩壊を1回起こすと、どんな原子核になるか。質量数と原子番号を答えよ(元素名はラドン Rn)。', a: '²²²₈₆Rn(質量数 222、原子番号 86)', exp: 'α粒子はヘリウムの原子核 ⁴₂He です。\nα崩壊では、質量数が 4、原子番号が 2 減ります。226−4＝222、88−2＝86。\n反応式 ²²⁶₈₈Ra → ²²²₈₆Rn＋⁴₂He で、質量数(226＝222＋4)と原子番号(88＝86＋2)がそれぞれ保存されていることを確かめましょう。' },
      { lv: 2, q: '半減期 8.0 日の放射性ヨウ素 131 がある。32 日後には、はじめの何分の1が崩壊せずに残っているか。また、はじめの 1/64 になるのは何日後か。', a: '1/16 が残る。48 日後に 1/64 になる。', exp: '残る割合は (1/2)^(t/T) です。\n32 日は半減期の 32/8.0＝4 回分なので (1/2)⁴＝1/16。\n1/64＝(1/2)⁶ なので、半減期の 6 回分で 6×8.0＝48 日後です。\n半減期の2倍の 16 日で「全部なくなる」のではなく、1/4 が残ります。くり返し半分になる、と考えるのがポイントです。' },
      { lv: 2, q: 'X線管で、電子を 3.0×10⁴ V の電圧で加速して陽極に当てた。発生する X線の最短波長を求めよ。(h＝6.6×10⁻³⁴ J·s、c＝3.0×10⁸ m/s、電気素量 1.6×10⁻¹⁹ C)', a: '約 4.1×10⁻¹¹ m', exp: '電子が得た運動エネルギー eV のすべてが1個の X線光子になったとき、光子のエネルギーが最大、つまり波長が最短になります。\neV＝hc/λ₀ より λ₀＝hc/(eV)。\nλ₀＝6.6×10⁻³⁴×3.0×10⁸/(1.6×10⁻¹⁹×3.0×10⁴)＝1.98×10⁻²⁵/4.8×10⁻¹⁵≒4.1×10⁻¹¹ m。\n最短波長は加速電圧だけで決まり、陽極の金属の種類にはよりません(特性 X線の波長は金属で決まります)。' },
      { lv: 3, q: 'ヘリウム原子核 ⁴₂He の質量は 4.0015 u である。陽子の質量を 1.0073 u、中性子の質量を 1.0087 u として、⁴₂He の結合エネルギーと、核子1個あたりの結合エネルギーを MeV で求めよ。(1 u の質量はエネルギー 931 MeV に相当する)', a: '結合エネルギー 約 28 MeV、核子1個あたり 約 7.1 MeV', exp: '⁴₂He は陽子2個・中性子2個からできています。ばらばらの質量の和は 2×1.0073＋2×1.0087＝4.0320 u。\n質量欠損 Δm＝4.0320−4.0015＝0.0305 u。\n結合エネルギー＝0.0305×931≒28.4 MeV、核子1個あたり 28.4/4≒7.1 MeV。\nヘリウムは軽い原子核の中でとくに安定で、核子1個あたりの結合エネルギーが前後の原子核より大きいことが知られています。' },
      { lv: 3, q: 'ウラン 235 の原子核1個が核分裂すると、約 200 MeV のエネルギーが出る。ウラン 235 が 1.0 g すべて核分裂したときに出るエネルギーは約何 J か。(アボガドロ定数 6.0×10²³ /mol、1 MeV＝1.6×10⁻¹³ J)', a: '約 8×10¹⁰ J', exp: 'ウラン 235 のモル質量は約 235 g/mol なので、1.0 g にふくまれる原子核の数は 6.0×10²³/235≒2.55×10²¹ 個。\n1個あたりのエネルギーは 200×1.6×10⁻¹³＝3.2×10⁻¹¹ J。\n全体で 2.55×10²¹×3.2×10⁻¹¹≒8.2×10¹⁰ J。\nこれは石炭およそ数トンを燃やしたときの熱に相当し、核反応のエネルギーが化学反応よりけた違いに大きいことが分かります。' }
    ],
    terms: [['光電効果', '光を当てた金属から電子が飛び出す現象'], ['光子', 'エネルギー hν、運動量 h/λ をもつ光の粒'], ['仕事関数', '電子を金属の外へ出すのに必要な最小のエネルギー'], ['物質波', '粒子がもつ波の性質。波長 λ＝h/(mv)'], ['エネルギー準位', '原子の中の電子がとれる、とびとびのエネルギーの値'], ['同位体', '原子番号が同じで、質量数(中性子の数)がちがう原子'], ['半減期', '放射性原子核の数が半分になるまでの時間'], ['質量欠損', '原子核の質量が、核子の質量の和より小さい分']],
    miss: ['光を強くすると、光電子の最大運動エネルギーが大きくなると考える。→ 強さが変えるのは光子の数(電子の数)だけ。1個のエネルギーは振動数で決まります。', 'eV と J を混ぜて計算する。→ 式に入れる前に単位を書き、h(J·s)を使うときは J に直します。1 eV＝1.6×10⁻¹⁹ J。', 'β崩壊で質量数が1減ると考える。→ 中性子が陽子に変わるだけなので、核子の数(質量数)は変わらず、原子番号が1増えます。', '半減期2回で全部なくなると考える。→ 毎回「残りの半分」になるので、2回で 1/4 です。'],
    sum: ['光子のエネルギー E＝hν、運動量 p＝h/λ。', '光電効果 K₀＝hν−W。限界振動数 hν₀＝W。光の強さは電子の数を決める。', '物質波の波長 λ＝h/(mv)。電子線も回折する。', 'ボーア模型:mvr＝nh/(2π)、hν＝E−E′。水素 Eₙ＝−13.6/n² eV。', 'α崩壊 Z−2・A−4、β崩壊 Z＋1。半減期 N＝N₀(1/2)^(t/T)。'],
    next: '物理の全単元を学び終えました。次は『入試レベル:物理基礎・化学基礎の総合』などの演習で、力学・電磁気の法則を組み合わせて使う練習をしましょう。'
  };
})(WPS.LESSONS);
